'use client';

import React, { useEffect, useMemo, useRef, useState, useCallback } from 'react';
import Hls from 'hls.js';
import mpegts from 'mpegts.js';
import { useTranslations } from 'next-intl';
import { cn } from '@/utils/cn';
import { toast } from 'react-hot-toast';
import { pictureInPictureUnavailableReason, type PictureInPictureVideoState } from '@/utils/pictureInPicture';
import {
  AlertCircle,
  Maximize,
  MessageSquare,
  MessageSquareOff,
  Pause,
  PictureInPicture2,
  Play,
  RefreshCw,
  Shield,
  Volume1,
  Volume2,
  X,
  VolumeX,
} from 'lucide-react';

/**
 * Số lần thử tải lại tối đa trước khi dừng và hiện nút "Thử tải lại". Retry vô hạn làm
 * trình duyệt tải lại liên tục khi luồng chết và người xem không thấy thông báo lỗi.
 */
const MAX_AUTORETRIES = 3;

export interface SportOLivePlayerProps {
  /** Mã định danh camera (streamId), ví dụ 'san1', 'vpsf2026_san1' */
  streamId?: string | null;
  /** Hoặc URL phát trực tiếp được trả về từ API backend */
  playbackUrl?: string | null;
  title?: string;
  aspectRatio?: string;
  onStateChange?: (state: 'connecting' | 'playing' | 'error') => void;
  /** Bảng điểm hiển thị đè lên khung hình, giống các dịch vụ live thực tế. */
  scoreboard?: React.ReactNode;
  /** Lớp đồ họa TV overlay đè lên video (H2H, Bracket,...) */
  overlay?: React.ReactNode;
  /** Mở/tắt khung thảo luận. Cha chỉ truyền khi cần nút này; hiện tại chỉ có trong toàn màn hình. */
  onToggleChat?: () => void;
  /** true = khung thảo luận đang hiện. */
  isChatOpen?: boolean;
  /** Mở/đóng bảng tính điểm trong toàn màn hình. Cha chỉ truyền khi người xem có quyền
      chấm điểm và đang toàn màn hình; bỏ trống thì không có nút. */
  onToggleScore?: () => void;
  /** true = bảng tính điểm đang mở. */
  isScoreOpen?: boolean;
  /** Vùng chứa toàn màn. Truyền vào để fullscreen bao cả khung chat bên phải
      (giống live Facebook); bỏ trống thì chỉ fullscreen riêng khung video. */
  fullscreenRef?: React.RefObject<HTMLElement | null>;
  /** Vùng chứa cha đang ở chế độ toàn màn: player bỏ ép tỉ lệ để lấp hết chiều cao. */
  fillContainerHeight?: boolean;
  /**
   * Trần chiều cao của khung (giá trị CSS, ví dụ `min(50dvh, 28rem)`). Khung vẫn lấy tỉ lệ thật của
   * luồng, chạm trần thì video letterbox: luồng dọc 9:16 không đẩy phần dưới ra khỏi màn hình.
   */
  maxHeight?: string;
  /** Báo ngược trạng thái toàn màn lên cha để cha và player không lệch nhau. */
  onFullscreenChange?: (isFullscreen: boolean) => void;
}

export interface ResolvedStreamSource {
  /** Chỉ có khi luồng là HTTP-FLV. mpegts.js không đọc được playlist HLS. */
  flvUrl: string | null;
  /** Luồng HLS cho Safari native, hls.js, và mọi nguồn không phải FLV. */
  hlsUrl: string | null;
}

/**
 * Phân tích URL phát thành cặp FLV/HLS.
 *
 * Quyết định quan trọng: `.m3u8` không phải FLV. Mọi URL HLS phải được giữ nguyên
 * và phát qua hls.js hoặc native HLS; không tự suy ra URL FLV thay thế.
 */
export function resolveStreamUrls(
  streamId?: string | null,
  playbackUrl?: string | null,
): ResolvedStreamSource | null {
  const url = playbackUrl?.trim();
  if (url) {
    if (url.includes('.live.flv')) {
      return { flvUrl: url, hlsUrl: url.replace('.live.flv', '/hls.m3u8') };
    }
    if (url.includes('/hls.m3u8')) {
