import { expect, test, type Page, type Route } from '@playwright/test';
import { createApiFixtureCorsHeaders } from './support/api-fixture-cors';

const organizer = {
  id: 'synthetic-organizer',
  email: 'organizer@example.test',
  fullName: 'Organizer Test',
  phoneNumber: '0900000000',
  roles: ['ORGANIZER'],
  gender: 'MALE',
  isEmailVerified: true,
  profile: { fullName: 'Organizer Test', phoneNumber: '0900000000' },
};

async function fulfillApi(route: Route, payload: unknown) {
  const request = route.request();
  const headers = {
    'content-type': 'application/json',
    ...createApiFixtureCorsHeaders(request.headers(), 'http://localhost:3001'),
  };

  if (request.method() === 'OPTIONS') {
    await route.fulfill({ status: 204, headers });
    return;
  }

  await route.fulfill({ status: 200, headers, json: payload });
}

async function openQuickCreate(page: Page) {
  await page.addInitScript((user) => {
    localStorage.setItem('auth-storage', JSON.stringify({
      state: { user, isAuthenticated: true },
      version: 0,
    }));
  }, organizer);

  await page.route('**/api/v1/**', async (route) => {
    const pathname = new URL(route.request().url()).pathname;

    if (pathname.endsWith('/users/profile')) {
      await fulfillApi(route, organizer);
      return;
    }

    if (pathname.endsWith('/categories')) {
      await fulfillApi(route, {
        data: [{ id: 'badminton', name: 'Cầu lông', slug: 'badminton', isActive: true }],
      });
      return;
    }

    if (pathname.endsWith('/tournaments/fees-config')) {
      await fulfillApi(route, { data: { allowEntryFees: false } });
      return;
    }

    await fulfillApi(route, { data: [] });
  });

  await page.goto('/organizer/tournaments/create', { waitUntil: 'domcontentloaded' });
}

test.use({ timezoneId: 'UTC' });

test('creates without early division settings or hidden region selectors', async ({ page }) => {
  await openQuickCreate(page);

  await expect(page.getByTestId(/^format-option-/)).toHaveCount(0);
…
});

