  const handleCreateCamera = async () => {
    if (!cameraName.trim()) {
      toast.error(livestreamTranslate("enterCameraName"));
      return;
    }

    const trimmedPlaybackUrl = playbackUrl.trim();
    if (cameraMode === "PULL" && !trimmedPlaybackUrl) {
      toast.error(livestreamTranslate("enterPlaybackUrl"));
      return;
    }

    setIsCreating(true);
    try {
      const response = await livestreamApi.createCamera(tournament.id, {
        name: cameraName.trim(),
        mode: cameraMode,
        // PULL ignores the protocol server-side; sending the selected one keeps
        // the RTMP/SRT choice meaningful instead of hardcoding RTMP.
        protocol: cameraProtocol,
        ...(cameraMode === "PULL" ? { playbackUrl: trimmedPlaybackUrl } : {}),
        ...(cameraCourtId ? { courtId: cameraCourtId } : {}),
      });
      setIsCameraModalOpen(false);
      setCameraName("");
      setPlaybackUrl("");
      setCameraCourtId("");
      setCameraProtocol("RTMP");
      await loadLivestreamData();
      toast.success(livestreamTranslate("cameraCreated"));

      // PUSH cameras are the ones AQP's Camera Station can be pointed at, so the
      // QR dialog follows the creation flow the operator just finished rather
      // than living on a separate screen.
      const created = response.data;
      if (created && created.mode === "PUSH") {
        setPendingQrCamera({ id: created.id, name: created.name });
      }
    } catch (err) {
      toast.error(getErrorMessage(err));
    } finally {
      setIsCreating(false);
    }
  };

