import { test } from '@playwright/test';

// TẠM THỜI: chụp cây accessibility của trang quản lý giải trên CI để viết lại quick-tournament.spec.ts. Xoá trước khi gộp.
const baseURL = process.env.PLAYWRIGHT_BASE_URL || 'http://localhost:3001';

test('explore manage page', async ({ page }) => {
  test.setTimeout(240_000);
  await page.goto(`${baseURL}/login`);
  await page.getByTestId('login-email-input').fill('admin1@gmail.com');
  await page.getByTestId('login-password-input').fill('123456');
  await page.getByTestId('login-submit-btn').click();
  await page.waitForURL(/\/home$/);

  await page.goto(`${baseURL}/organizer/tournaments/create`);
  await page.getByTestId('tournament-name-input').fill(`Explore ${Date.now()}`);
  await page.getByRole('button', { name: 'Cầu lông' }).click();
  await page.getByTestId('venue-name-input').fill('Sân Explore');
  await page.getByTestId('location-address-input').fill('1 Đường Explore, Hà Nội');
  await page.getByTestId('submit-quick-create-btn').click();
  await page.waitForURL(/\/organizer\/tournaments\/[^/]+\/manage/, { timeout: 20000 });
  const id = new URL(page.url()).pathname.split('/')[3];

  for (const tab of ['', 'divisions', 'registration', 'bracket', 'court_schedule', 'livestream', 'settings', 'basic', 'schedule', 'permissions']) {
    await page.goto(`${baseURL}/organizer/tournaments/${id}/manage${tab ? `?tab=${tab}` : ''}`);
    await page.waitForTimeout(3000);
    console.log(`=== EXPLORE TAB ${tab || 'overview'} url=${page.url()}\n${await page.locator('main').ariaSnapshot()}`);
  }

  await page.goto(`${baseURL}/organizer/tournaments/${id}/manage?tab=divisions`);
  await page.getByRole('button', { name: 'Thêm nội dung' }).first().click();
  await page.waitForTimeout(1500);
  console.log(`=== EXPLORE DIALOG division\n${await page.locator('body').ariaSnapshot()}`);

  await page.goto(`${baseURL}/organizer/tournaments/${id}/manage?tab=livestream`);
  await page.waitForTimeout(2000);
  await page.getByRole('button', { name: 'Thêm camera' }).first().click().catch(() => console.log('=== EXPLORE no add-camera button'));
  await page.waitForTimeout(1500);
  console.log(`=== EXPLORE DIALOG camera\n${await page.locator('body').ariaSnapshot()}`);

  await page.goto(`${baseURL}/organizer/tournaments`);
  await page.waitForTimeout(3000);
  console.log(`=== EXPLORE LIST\n${await page.locator('main').ariaSnapshot()}`);
});

