import { test, expect, type Page } from '@playwright/test';

// Mặc định localhost. KHÔNG fallback về production để tránh test tạo dữ liệu thật trên site thật.
const baseURL = process.env.PLAYWRIGHT_BASE_URL || process.env.FRONTEND_URL || 'http://localhost:3001';
test.describe.serial('Quick Tournament Creation and Edit Flow', () => {
  test.setTimeout(120_000);

  const userEmail = 'admin1@gmail.com';
  const userPassword = '123456';
  const tournamentName = `Test Quick Tournament ${Date.now()}`;
  const editedTournamentName = `Edited Quick Tournament ${Date.now()}`;
  // Gán ở test tạo giải, test sửa giải dùng lại (describe.serial chạy cùng worker, retry chạy lại cả nhóm).
  let tournamentId = '';

  const manageUrl = (tab?: string) =>
    `${baseURL}/organizer/tournaments/${tournamentId}/manage${tab ? `?tab=${tab}` : ''}`;
  const tournamentHeading = (page: Page, name: string) => page.getByRole('heading', { level: 1, name, exact: true });
  // Trang quản lý tự lưu thông tin giải (PATCH /tournaments/:id, trễ ~1 giây), không còn nút lưu riêng.
  const waitForAutoSave = (page: Page, mustContain: string) =>
    page.waitForResponse((response) =>
      response.request().method() === 'PATCH' &&
      new URL(response.url()).pathname.endsWith(`/tournaments/${tournamentId}`) &&
      (response.request().postData() ?? '').includes(mustContain) &&
      response.ok(),
    );
  // Bỏ bản nháp localStorage của trang quản lý để lần tải lại đọc dữ liệu từ server.
  const reloadFromServer = async (page: Page) => {
    await page.evaluate(() => {
      for (const key of Object.keys(localStorage)) {
        if (key.startsWith('sporto:tournament-manage-draft:')) localStorage.removeItem(key);
      }
    });
    await page.goto(manageUrl());
  };

  test.beforeEach(async ({ page }) => {
    const sleep = async () => page.waitForTimeout(500);
    // Login
    await page.goto(`${baseURL}/login`);
    await sleep();

    await page.getByTestId('login-email-input').fill(userEmail);
    await sleep();
    await page.getByTestId('login-password-input').fill(userPassword);
    await sleep();
    await page.getByTestId('login-submit-btn').click();
    await sleep();
    // Wait for navigation to home
    await expect(page).toHaveURL(/\/home$/);
    await sleep();
  });

  test('Create a quick tournament', async ({ page }) => {
    const sleep = async () => page.waitForTimeout(500);

    // Navigate to quick create page and clean any old draft
    await page.goto(`${baseURL}/organizer/tournaments/create`);
    await page.evaluate(() => localStorage.clear());
    await sleep();

    // Fill in the basic info using data-testid attributes
    await page.getByTestId('tournament-name-input').fill(tournamentName);
    await page.getByRole('button', { name: 'Cầu lông' }).click();
    await page.getByTestId('venue-name-input').fill('Sân Cầu Lông Kỳ Hòa');
    await page.getByTestId('location-address-input').fill('123 Đường Example, Hà Nội');
    await sleep();

    // Pick a date (today + 7 days) using the datetime picker
    const startDateInput = page.locator('input[name="startDate"]');
    const futureDate = new Date();
    futureDate.setDate(futureDate.getDate() + 7);
    futureDate.setHours(9, 0, 0, 0);
    const iso = futureDate.toISOString().slice(0, 16);
    await startDateInput.fill(iso);
    await sleep();

    // Submit the form
    await page.getByTestId('submit-quick-create-btn').click();

    // Expect to be redirected to the manage page of the new tournament
    await expect(page).toHaveURL(/\/organizer\/tournaments\/[^/]+\/manage/, { timeout: 20000 });
    tournamentId = new URL(page.url()).pathname.split('/')[3];
    await expect(tournamentHeading(page, tournamentName)).toBeVisible();

    // Giải mới chưa có nội dung thi đấu: thêm "Đơn nam".
    await page.goto(manageUrl('divisions'));
    const divisionsSection = page.getByTestId('manage-inline-divisions');
    await expect(divisionsSection.getByTestId('manage-divisions-empty')).toBeVisible();
    await divisionsSection.getByTestId('manage-divisions-add').click();
    const divisionDialog = page.getByRole('dialog');
    await expect(divisionDialog).toBeVisible();
    await divisionDialog.getByRole('button', { name: 'Đơn Nam' }).click();
    await divisionDialog.getByLabel('Tên nội dung (tuỳ chọn)').fill('Đơn nam');
    await divisionDialog.getByRole('button', { name: 'Thêm', exact: true }).click();
    await expect(divisionDialog).toBeHidden();
    await expect(divisionsSection.getByText('Đơn nam', { exact: true })).toBeVisible();
  });

  test('Edit tournament and configure tabs from manage page', async ({ page }) => {
