    // Vào trang quản lý từ danh sách giải của Ban tổ chức.
    await page.goto(`${baseURL}/organizer/tournaments`);
    await page.locator(`a[href="/organizer/tournaments/${tournamentId}/manage"]`).first().click();
    await expect(page).toHaveURL(new RegExp(`/organizer/tournaments/${tournamentId}/manage`), { timeout: 20000 });
    await expect(tournamentHeading(page, tournamentName)).toBeVisible();

    // --- Thông tin chung: đổi tên, tự lưu lên server ---
    await page.goto(manageUrl('basic'));
