    const nameSaved = waitForAutoSave(page, editedTournamentName);
    await page.getByRole('textbox', { name: 'Tên giải đấu' }).fill(editedTournamentName);
    await nameSaved;
    await reloadFromServer(page);
    await expect(tournamentHeading(page, editedTournamentName)).toBeVisible();

    // --- Liên hệ & Mã mời: SĐT và email BTC, tự lưu lên server ---
    await page.goto(manageUrl('basic'));
