    await sleep();
    await page.getByTestId('login-password-input').fill(userPassword);
    await sleep();
    await page.getByTestId('login-submit-btn').click();
    await sleep();
    // Wait for navigation to home
    await expect(page).toHaveURL(/\/home$/);
    await sleep();
  });

