  const reloadFromServer = async (page: Page, tab?: string) => {
    await page.evaluate(() => {
      for (const key of Object.keys(localStorage)) {
        if (key.startsWith('sporto:tournament-manage-draft:')) localStorage.removeItem(key);
      }
    });
    await page.goto(manageUrl(tab));
  };

  test.beforeEach(async ({ page }) => {
    const sleep = async () => page.waitForTimeout(500);
    // Login
    await page.goto(`${baseURL}/login`);
    await sleep();

    await page.getByTestId('login-email-input').fill(userEmail);
    await sleep();
    await page.getByTestId('login-password-input').fill(userPassword);
    await sleep();
    await page.getByTestId('login-submit-btn').click();
    await sleep();
    // Wait for navigation to home
    await expect(page).toHaveURL(/\/home$/);
    await sleep();
  });

  test('Create a quick tournament', async ({ page }) => {
    const sleep = async () => page.waitForTimeout(500);

    // Navigate to quick create page and clean any old draft
    await page.goto(`${baseURL}/organizer/tournaments/create`);
    // Chỉ xoá bản nháp tạo giải: localStorage.clear() xoá cả trạng thái đăng nhập (run CI 38856063619 bị đá về /login).
    await page.evaluate(() => localStorage.removeItem('sporto:tournament-quick-draft:public'));
    await sleep();

    // Fill in the basic info using data-testid attributes
    await page.getByTestId('tournament-name-input').fill(tournamentName);
    await page.getByRole('button', { name: 'Cầu lông' }).click();
    await page.getByTestId('venue-name-input').fill('Sân Cầu Lông Kỳ Hòa');
    await page.getByTestId('location-address-input').fill('123 Đường Example, Hà Nội');
    await sleep();

    // Pick a date (today + 7 days) using the datetime picker
    const startDateInput = page.locator('input[name="startDate"]');
    const futureDate = new Date();
    futureDate.setDate(futureDate.getDate() + 7);
    futureDate.setHours(9, 0, 0, 0);
    const iso = futureDate.toISOString().slice(0, 16);
    await startDateInput.fill(iso);
    await sleep();

    // Submit the form
    await page.getByTestId('submit-quick-create-btn').click();

    // Expect to be redirected to the manage page of the new tournament
    await expect(page).toHaveURL(/\/organizer\/tournaments\/[^/]+\/manage/, { timeout: 20000 });
    tournamentId = new URL(page.url()).pathname.split('/')[3];
    await expect(tournamentHeading(page, tournamentName)).toBeVisible();

    // Thêm nội dung "Đơn nam" (giải tạo nhanh đã có sẵn một nội dung mặc định).
    await page.goto(manageUrl('divisions'));
    const divisionsRegion = page.getByRole('region', { name: 'Nội dung thi đấu' });
    await divisionsRegion.getByRole('button', { name: 'Thêm nội dung' }).click();
    const divisionDialog = page.getByRole('dialog', { name: 'Thêm nội dung thi đấu' });
    await divisionDialog.getByRole('button', { name: 'Đơn Nam', exact: true }).click();
    await divisionDialog.getByRole('textbox', { name: 'Tên nội dung (tuỳ chọn)' }).fill('Đơn nam');
    await divisionDialog.getByRole('button', { name: 'Thêm', exact: true }).click();
    await expect(divisionDialog).toBeHidden();
    await expect(divisionsRegion.getByRole('button', { name: /^Đơn nam/ }).first()).toBeVisible();
  });

  test('Edit tournament and configure tabs from manage page', async ({ page }) => {
    test.skip(!tournamentId, 'Cần giải do test tạo giải ở trên tạo ra');

    // Vào trang quản lý từ danh sách giải của Ban tổ chức.
    await page.goto(`${baseURL}/organizer/tournaments`);
    await page.getByRole('link', { name: 'Quản lý', exact: true }).and(page.locator(`[href="/organizer/tournaments/${tournamentId}/manage"]`)).click();
    await expect(page).toHaveURL(new RegExp(`/organizer/tournaments/${tournamentId}/manage`), { timeout: 20000 });
    await expect(tournamentHeading(page, tournamentName)).toBeVisible();

    // --- Thông tin chung: đổi tên, tự lưu lên server ---
    await page.goto(manageUrl('basic'));
    await page.getByRole('button', { name: 'Thông tin chung' }).click();
    const nameSaved = waitForAutoSave(page, editedTournamentName);
    await page.getByRole('textbox', { name: 'Tên giải đấu' }).fill(editedTournamentName);
    await nameSaved;
    await reloadFromServer(page);
    await expect(tournamentHeading(page, editedTournamentName)).toBeVisible();

    // --- Liên hệ & Mã mời: SĐT và email BTC, tự lưu lên server ---
    await page.goto(manageUrl('basic'));
    await page.getByRole('button', { name: 'Liên hệ & Mã mời' }).click();
    const contactSaved = waitForAutoSave(page, 'contact@sporto.test');
    await page.getByPlaceholder('0987654321').fill('0912345678');
    await page.getByPlaceholder('btc@vndcsport.vn').fill('contact@sporto.test');
    await contactSaved;
    await reloadFromServer(page, 'basic');
    await page.getByRole('button', { name: 'Liên hệ & Mã mời' }).click();
    await expect(page.getByPlaceholder('0987654321')).toHaveValue('0912345678');
    await expect(page.getByPlaceholder('btc@vndcsport.vn')).toHaveValue('contact@sporto.test');

    // --- Địa điểm & Cụm sân: thêm địa điểm mới ---
    await page.goto(manageUrl('schedule'));
    await page.getByRole('button', { name: 'Thêm địa điểm mới' }).click();
    await page.getByPlaceholder('VD: CLB Cầu Lông Kỳ Hòa, Sân Pickleball Hồ Bơi...').fill('Sân Cầu Lông Hồ Tây Mới');
    await page.getByPlaceholder('VD: 123 Lê Lợi, Phường Bến Nghé, Quận 1...').fill('456 Đường Lạc Long Quân, Hà Nội');
    await page.getByRole('button', { name: 'Tạo địa điểm' }).click();
    await expect(page.getByRole('heading', { level: 3, name: 'Sân Cầu Lông Hồ Tây Mới' })).toBeVisible();

    // --- Cài đặt > Cấu hình đăng ký: chuyển sang Xét duyệt ---
    const manageNav = page.getByRole('region', { name: 'Quản lý giải đấu' });
    await manageNav.getByRole('link', { name: 'Cài đặt', exact: true }).click();
    await expect(page).toHaveURL(/[?&]tab=settings/);
    await page.getByRole('button', { name: /^Xét duyệt/ }).click();
    await page.getByRole('button', { name: 'Lưu cài đặt đăng ký' }).click();
    await expect(page.getByText('Lưu thông tin đăng ký thành công!')).toBeVisible();

    // --- Bảng đấu: chưa có VĐV nên chưa tạo được sơ đồ ---
    await manageNav.getByRole('link', { name: 'Bảng đấu', exact: true }).click();
    await expect(page).toHaveURL(/[?&]tab=bracket/);
    await expect(page.getByRole('button', { name: 'Tạo bracket' })).toBeDisabled();

    // --- Camera: tạo camera ---
    await manageNav.getByRole('link', { name: 'Camera', exact: true }).click();
    await expect(page).toHaveURL(/[?&]tab=livestream/);
    await page.getByRole('button', { name: 'Thêm camera' }).click();
    const cameraDialog = page.getByRole('dialog', { name: 'Thêm camera' });
    await cameraDialog.getByRole('textbox', { name: 'Tên camera' }).fill('Camera Sân 1 - HD');
    // CI không có AQVISION_PUSH_HOST nên camera PUSH bị 503; PULL dán URL phát sẵn không gọi AQP.
    await cameraDialog.getByRole('button', { name: /^PULL/ }).click();
    await cameraDialog.getByPlaceholder('Ví dụ: https://media.aqvision.net/live/san1.live.flv').fill('https://media.example.test/live/san1/hls.m3u8');
    const cameraResponse = page.waitForResponse((response) =>
      response.request().method() === 'POST' &&
      new URL(response.url()).pathname.endsWith(`/tournaments/${tournamentId}/cameras`),
    );
    await cameraDialog.getByRole('button', { name: 'Tạo camera' }).click();
    const createdCamera = await cameraResponse;
    expect(createdCamera.status(), await createdCamera.text()).toBe(201);
    await expect(cameraDialog).toBeHidden();
    await expect(page.getByTitle('Camera Sân 1 - HD').first()).toBeVisible();

    // --- Phân quyền: thêm user8 vào Ban tổ chức ---
    await page.goto(manageUrl('permissions'));
    await expect(page.getByRole('heading', { level: 2, name: 'Quản lý phân quyền' })).toBeVisible();
    await page.getByRole('textbox', { name: 'email@example.com' }).fill('user8@gmail.com');
    await page.getByRole('button', { name: 'Thêm', exact: true }).click();
    await expect(page.getByText('user8@gmail.com').first()).toBeVisible();
  });
});

