import axios from 'axios';
import { useCallback, useEffect, useRef, useState } from 'react';
import { useTranslations } from 'next-intl';
import { toast } from 'react-hot-toast';
import {
  livestreamApi,
  type MatchStreamControlState,
  type RecordingStatus,
} from '@/features/tournaments/api';
import { getErrorMessage, isHttpStatusError } from '@/utils/error';

interface UseMatchStreamControlOptions {
  matchId: string;
  enabled: boolean;
  /**
   * Gọi sau khi server đã ghi nhận Dừng/Bắt đầu, kể cả khi modal đã đóng giữa chừng:
   * video thuộc về trang, không thuộc về modal.
   */
  onToggled?: () => void;
}

function normalizeStreamStatus(value: unknown): MatchStreamControlState['streamStatus'] {
  switch (value) { … }
}

function normalizeControlState(
  value: unknown,
  matchId: string,
): MatchStreamControlState | null {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return null;
  }

  const candidate = value as Record<string, unknown>;
  if (candidate.matchId !== matchId || typeof candidate.hasCamera !== 'boolean') {
    return null;
  }

  if (!candidate.hasCamera) {
    return { matchId, hasCamera: false, streamStatus: null };
  }

  const streamStatus = normalizeStreamStatus(candidate.streamStatus);
  if (!streamStatus) { … }

  return { matchId, hasCamera: true, streamStatus };
}

function isServerFailure(error: unknown): boolean {
  return axios.isAxiosError(error) && (error.response?.status ?? 0) >= 500;
}

export function useMatchStreamControl({
  matchId,
  enabled,
  onToggled,
}: UseMatchStreamControlOptions) { … }

