export function useMatchStreamControl({
…
  onToggled,
}: UseMatchStreamControlOptions) {
  const tErrors = useTranslations('Errors');
  const tMatch = useTranslations('Match');
  const stateRef = useRef<MatchStreamControlState | null>(null);
  const requestIdRef = useRef(0);
  const mutationPendingRef = useRef(false);
  const enabledRef = useRef(enabled);
  const matchIdRef = useRef(matchId);
  const onToggledRef = useRef(onToggled);
  const [controlState, setControlState] = useState<MatchStreamControlState | null>(null);
  const [isPending, setIsPending] = useState(false);

  const setCurrentState = useCallback((next: MatchStreamControlState | null) => {
    stateRef.current = next;
    setControlState(next);
  }, []);
  /**
   * Reads the minimal control-state projection for one match. `requestId` fences
   * the write so a superseded read can never repaint the current modal.
   * `reportError` toasts only for the modal-open read; background reconciliation
   * stays quiet because a failure there just keeps the last confirmed state.
   */
  const readControlState = useCallback(
    async (targetMatchId: string, requestId: number, reportError = false) => {
      try {
        const response =
          await livestreamApi.getMatchStreamControlState(targetMatchId);
        if (requestId !== requestIdRef.current) return;
        setCurrentState(normalizeControlState(response.data, targetMatchId));
      } catch (error) {
        if (requestId !== requestIdRef.current) return;
        if (isHttpStatusError(error, 403)) {
          setCurrentState(null);
          return;
        }
        if (!reportError || isServerFailure(error)) return;
        toast.error(getErrorMessage(error, tErrors('generic')));
      }
    },
    [setCurrentState, tErrors],
  );
  const reset = useCallback(() => {
    enabledRef.current = false;
    requestIdRef.current += 1;
    setCurrentState(null);
  }, [setCurrentState]);

  useEffect(() => {
    enabledRef.current = enabled;
    matchIdRef.current = matchId;
    if (!enabled) {
      requestIdRef.current += 1;
      return;
    }

    const requestId = ++requestIdRef.current;
    void readControlState(matchId, requestId, true);

    return () => {
      if (requestId === requestIdRef.current) {
        requestIdRef.current += 1;
        enabledRef.current = false;
      }
    };
  }, [enabled, matchId, readControlState]);

  useEffect(() => {
    onToggledRef.current = onToggled;
  }, [onToggled]);

  const toggle = useCallback(async () => {
    const current = stateRef.current;
    if (
      !enabledRef.current ||
      matchIdRef.current !== matchId ||
      !current ||
      current.matchId !== matchId ||
      !current.hasCamera ||
      mutationPendingRef.current
    ) return;

    const requestId = requestIdRef.current;
    const isStopping = current.streamStatus === 'LIVE';

    mutationPendingRef.current = true;
    setIsPending(true);

    try {
      let mutationStreamStatus: MatchStreamControlState['streamStatus'] | undefined;
      let recordingStatus: RecordingStatus | undefined;

      if (isStopping) {
        const response = await livestreamApi.stopMatchStream(matchId);
        mutationStreamStatus = response.data?.streamStatus;
        recordingStatus = response.data?.recordingStatus;
      } else {
        const response = await livestreamApi.startMatchStream(matchId);
        mutationStreamStatus = response.data?.livestream?.streamStatus;
        recordingStatus = response.data?.recordingStatus;
      }
      onToggledRef.current?.();

      const isCurrentView =
        enabledRef.current &&
        matchIdRef.current === matchId &&
        requestId === requestIdRef.current;

      if (!isCurrentView) {
        // The modal closed (and may have reopened) while this mutation was in
        // flight, so the response describes a view that no longer exists. Drop
        // the payload; when the same match is open again, re-read the
        // authoritative control state instead of trusting the stale result.
        if (enabledRef.current && matchIdRef.current === matchId) {
          await readControlState(matchId, ++requestIdRef.current);
        }
        return;
      }
      if (recordingStatus === 'PENDING') {
        toast(tMatch('recordingPending'), { icon: '⚠' });
      }

      const confirmedStatus = normalizeStreamStatus(mutationStreamStatus);

      if (!confirmedStatus) {
        // Success without a recognized status is not confirmation: keep the last
        // confirmed state until an authorized read reports the new one.
        await readControlState(matchId, ++requestIdRef.current);
        return;
      }

      setCurrentState({ matchId, hasCamera: true, streamStatus: confirmedStatus });
    } catch (error) {
      const isSameOpenMatch = enabledRef.current && matchIdRef.current === matchId;
      if (requestId !== requestIdRef.current) {
        // A superseded rejection says nothing about the view that is open now,
        // so it neither repaints nor toasts it. The mutation may still have
        // committed server-side (rejection after commit), so reconcile with a
        // fresh read whenever the same match is open again.
        if (isSameOpenMatch) {
          await readControlState(matchId, ++requestIdRef.current);
        }
        return;
      }
      if (!isSameOpenMatch) return;
      if (isHttpStatusError(error, 403)) {
        setCurrentState(null);
        toast.error(tMatch('permissionDenied'));
        return;
      }
      if (!isServerFailure(error)) {
        toast.error(getErrorMessage(error, tErrors('generic')));
      }
    } finally {
      mutationPendingRef.current = false;
      setIsPending(false);
    }
  }, [matchId, readControlState, setCurrentState, tErrors, tMatch]);

  return {
    canControl:
      controlState?.matchId === matchId && controlState?.hasCamera === true,
    isLive:
      controlState?.matchId === matchId && controlState?.streamStatus === 'LIVE',
    isPending,
    toggle,
    reset,
  };
}

