"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import { Copy, Loader2, QrCode } from "lucide-react";
import { QRCodeSVG } from "qrcode.react";
import toast from "react-hot-toast";

import { Button } from "@/components/ui/Button";
import { livestreamApi, type AqpCameraStreamKey } from "@/features/tournaments/api";
import { getErrorMessage } from "@/utils/error";

interface AqpStreamKeyControlsProps {
  camera: { id: string; name: string };
  onRefresh: () => Promise<void>;
  /**
   * Issue a key automatically once the camera's state has loaded and it has none. Only the
   * camera-creation flow sets this; opening the dialog from the list never does.
   */
  autoIssue?: boolean;
}

export function AqpStreamKeyControls({
  camera,
  onRefresh,
  autoIssue = false,
}: AqpStreamKeyControlsProps) {
  const t = useTranslations("OrganizerLivestream");
  const [result, setResult] = useState<AqpCameraStreamKey | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isMutating, setIsMutating] = useState(false);
  const [isRevoking, setIsRevoking] = useState(false);
  const [isEditingStreamName, setIsEditingStreamName] = useState(false);
  const [newStreamName, setNewStreamName] = useState("");
  const requestId = useRef(0);
  // The camera whose key was already issued automatically (one attempt per camera).
  const autoIssuedFor = useRef<string | null>(null);

  const loadStreamKey = useCallback(
    async (cameraId: string) => {
      const currentRequest = ++requestId.current;
      try {
        const response = await livestreamApi.getAqpStreamKey(cameraId);
        if (requestId.current === currentRequest) {
          setResult(response.data ?? null);
          setNewStreamName(response.data?.camera.streamName ?? "");
        }
      } catch (error) {
        if (requestId.current === currentRequest) toast.error(getErrorMessage(error));
      } finally {
        if (requestId.current === currentRequest) setIsLoading(false);
      }
    },
    [],
  );

  useEffect(() => {
    const currentRequest = ++requestId.current;
    let active = true;
    void livestreamApi
      .getAqpStreamKey(camera.id)
      .then((response) => {
        if (!active || requestId.current !== currentRequest) return;
        setResult(response.data ?? null);
        setNewStreamName(response.data?.camera.streamName ?? "");
      })
      .catch((error: unknown) => {
        if (active && requestId.current === currentRequest) {
          toast.error(getErrorMessage(error));
        }
      })
      .finally(() => {
        if (active && requestId.current === currentRequest) setIsLoading(false);
      });
    return () => {
      active = false;
      requestId.current += 1;
    };
  }, [camera.id]);

  const copyValue = async (value: string, label: string) => {
    try {
      await navigator.clipboard.writeText(value);
      toast.success(t("copied", { label }));
    } catch (error) {
      toast.error(getErrorMessage(error));
    }
  };

  const createStreamKey = async () => {
    setIsMutating(true);
    try {
      const response = await livestreamApi.createAqpStreamKey(camera.id);
      setResult(response.data ?? null);
      await onRefresh();
      toast.success(t("aqpKeyCreated"));
    } catch (error) {
      toast.error(getErrorMessage(error));
      await loadStreamKey(camera.id);
    } finally {
      setIsMutating(false);
    }
  };

  const rotateStreamKey = async () => {
    setIsMutating(true);
    try {
      const response = await livestreamApi.rotateAqpStreamKey(camera.id);
      setResult(response.data ?? null);
      toast.success(t("aqpRotateKeyDone"));
    } catch (error) {
      toast.error(getErrorMessage(error));
      await loadStreamKey(camera.id);
    } finally {
      setIsMutating(false);
    }
  };

  const renameStreamKey = async () => {
    const stream = newStreamName.trim();
    if (!stream) return;
    setIsMutating(true);
    try {
      const response = await livestreamApi.renameAqpStreamKey(camera.id, stream);
      setResult(response.data ?? null);
      setNewStreamName(response.data?.camera.streamName ?? "");
      setIsEditingStreamName(false);
      await onRefresh();
      toast.success(t("aqpStreamRenamed"));
    } catch (error) {
      toast.error(getErrorMessage(error));
      await loadStreamKey(camera.id);
      await onRefresh();
    } finally {
      setIsMutating(false);
    }
  };

  const revokeStreamKey = async () => {
    if (!window.confirm(t("aqpDeleteConfirm"))) return;
    setIsRevoking(true);
    try {
      const response = await livestreamApi.revokeAqpStreamKey(camera.id);
      if (!response.data?.keyRevoked || !response.data.disconnected) {
        throw new Error(t("aqpDeleteIncomplete"));
      }
      // The organiser just deleted this key. Mark the camera as handled before reloading:
      // AQP may answer 404 for the deleted key, the backend then clears streamKeyId and the
      // camera reads as "never had a key", which must not trigger an automatic new key.
      autoIssuedFor.current = camera.id;
      await loadStreamKey(camera.id);
      await onRefresh();
      toast.success(t("aqpKeyDeleted"));
    } catch (error) {
      toast.error(getErrorMessage(error));
      await loadStreamKey(camera.id);
    } finally {
      setIsRevoking(false);
    }
  };

  // The camera-creation flow (`autoIssue`) issues the key as soon as the camera's state has
  // loaded, so the operator sees the QR without another click. Opening the dialog from the
  // list never does: "no key id" can also mean AQP forgot a key the organiser deleted, and a
  // new key must only ever come from an explicit click. Within the creation flow it is one
  // attempt per camera (the ref also absorbs StrictMode's second run), never after the
  // organiser deleted the key here, and a failure leaves the manual button instead of retrying.
  useEffect(() => {
    if (!autoIssue) return;
    if (isLoading || isMutating || isRevoking || !result) return;
    if (result.camera.id !== camera.id) return;
    if (result.streamKeyId || result.rtmp) return;
    if (autoIssuedFor.current === camera.id) return;
    autoIssuedFor.current = camera.id;
    void createStreamKey();
    // createStreamKey is recreated every render and closes over camera.id, onRefresh,
    // t and (on its error path) loadStreamKey. Keying this effect on its identity would
    // re-run it on every render; the ref above is what bounds it to one attempt per camera.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoIssue, camera.id, isLoading, isMutating, isRevoking, result]);

  return (
    <div className="min-w-0 space-y-4">
      {isLoading ? (
        <div role="status" className="flex items-center gap-2 py-4 text-sm text-slate-500">
          <Loader2 className="h-4 w-4 animate-spin" />
          {t("aqpLoadingKey")}
        </div>
      ) : null}

      {result && !isLoading ? (
        <div className="space-y-2">
          <div className="flex flex-wrap items-center gap-2">
            {isEditingStreamName ? (
              <input
                aria-label={t("aqpStreamName")}
                value={newStreamName}
                onChange={(event) => setNewStreamName(event.target.value)}
                className="min-w-0 flex-1 rounded-md border border-slate-300 px-3 py-2 font-mono text-sm"
                disabled={isMutating}
              />
            ) : (
              <span className="min-w-0 flex-1 truncate rounded-md bg-slate-50 px-3 py-2 font-mono text-sm">
                {result.camera.streamName}
              </span>
            )}
            {isEditingStreamName ? (
              <>
                <Button
                  size="sm"
                  onClick={() => void renameStreamKey()}
                  disabled={
                    isMutating ||
                    !newStreamName.trim() ||
                    newStreamName.trim() === result.camera.streamName
                  }
                >
                  {t("aqpSaveRename")}
                </Button>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => {
                    setNewStreamName(result.camera.streamName);
                    setIsEditingStreamName(false);
                  }}
                  disabled={isMutating}
                >
                  {t("aqpCancelRename")}
                </Button>
              </>
            ) : (
              <Button
                size="sm"
                variant="outline"
                onClick={() => setIsEditingStreamName(true)}
                disabled={isMutating || isRevoking || Boolean(result.rtmp)}
                title={result.rtmp ? t("aqpRenameNeedsDelete") : undefined}
              >
                {t("aqpRenameStream")}
              </Button>
            )}
          </div>
        </div>
      ) : null}

      {result?.qrPayloadString ? (
        <div className="min-w-0 space-y-3 rounded-lg border border-slate-200 bg-slate-50 p-4">
          <div className="flex items-center justify-between gap-3">
            <p className="text-sm font-semibold text-slate-800">
              {result.status ?? t("aqpUnknownStatus")}
            </p>
            <span className="rounded-full bg-emerald-100 px-2 py-1 text-xs font-semibold text-emerald-700">
              {t("aqpKeyReady")}
            </span>
          </div>
          <div className="flex justify-center rounded-lg bg-white p-3">
            <QRCodeSVG value={result.qrPayloadString} size={200} level="M" />
          </div>
          <p className="text-xs leading-snug text-amber-700">{t("aqpQrSecretWarning")}</p>
          {result.rtmp ? (
            <div className="space-y-2 border-t border-slate-200 pt-3">
              <p className="text-xs font-bold text-slate-500">{t("aqpRtmpHeading")}</p>
              {[
                { label: t("aqpRtmpServer"), value: result.rtmp.server },
                { label: t("aqpRtmpStreamKey"), value: result.rtmp.streamKey },
              ].map((row) => (
                <div
                  key={row.label}
                  className="flex min-w-0 items-center gap-3 rounded-lg border border-slate-200 bg-white px-3 py-2"
                >
                  <span className="shrink-0 text-xs font-bold text-slate-500">{row.label}:</span>
                  <span className="min-w-0 flex-1 break-all font-mono text-xs font-bold text-slate-900 select-all">
                    {row.value}
                  </span>
                  <button
                    type="button"
                    aria-label={row.label}
                    onClick={() => void copyValue(row.value, row.label)}
                    title={row.label}
                    className="shrink-0 cursor-pointer rounded-md p-1.5 text-blue-600 transition-colors hover:bg-blue-50 hover:text-blue-700"
                  >
                    <Copy className="h-4 w-4" />
                  </button>
                </div>
              ))}
            </div>
          ) : null}
        </div>
      ) : null}

      {!isLoading && result && !result.rtmp ? (
        <Button
          onClick={() => void createStreamKey()}
          disabled={isMutating || isRevoking}
          className="w-full bg-blue-600 text-white hover:bg-blue-700"
        >
          {isMutating ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <QrCode className="mr-2 h-4 w-4" />}
          {result.streamKeyId ? t("aqpReissueKey") : t("aqpCreateKey")}
        </Button>
      ) : null}
      {!isLoading && !result ? (
        <Button
          variant="outline"
          onClick={() => {
            setIsLoading(true);
            void loadStreamKey(camera.id);
          }}
        >
          {t("aqpRetryLoad")}
        </Button>
      ) : null}

      <div className="flex flex-wrap items-center gap-2 border-t border-slate-200 pt-4">
        {result?.rtmp ? (
          <>
            <Button
              variant="outline"
              size="sm"
              onClick={() => void rotateStreamKey()}
              disabled={isMutating || isRevoking}
              title={t("aqpRotateKeyHint")}
            >
              {isMutating ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
              {t("aqpRotateKey")}
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={() => void revokeStreamKey()}
              disabled={isMutating || isRevoking}
            >
              {isRevoking ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
              {t("aqpDeleteKey")}
            </Button>
          </>
        ) : null}
      </div>
    </div>
  );
}

