test('a failed automatic key keeps a manual button and does not retry on its own', async ({
  page,
}) => {
  const harness = await installHarness(page, [], { createFails: true });
  await gotoManage(page);
  await createCameraFromDialog(page);

  const dialog = page.getByRole('dialog');
  await expect.poll(() => harness.createAqpCalls.length).toBe(1);
  await expect(dialog.getByRole('button', { name: COPY.createAqpKey })).toBeVisible();
  await expect(dialog.locator('svg[width="200"]')).toHaveCount(0);
  await page.waitForTimeout(300);
  expect(harness.createAqpCalls).toHaveLength(1);
});

test('deleting a key never issues a new one, even when AQP forgets the key id afterwards', async ({
  page,
}) => {
  const linkedCamera = { ...createdPushCamera, hasAqpStreamKey: true };
  const harness = await installHarness(page, [linkedCamera], { forgetKeyOnDelete: true });
  page.on('dialog', (dialog) => void dialog.accept());
  await gotoManage(page);
  await page.getByRole('button', { name: COPY.qrAction, exact: true }).click();

  const dialog = page.getByRole('dialog');
  await expect(dialog.locator('svg[width="200"]')).toBeVisible();

  await dialog.getByRole('button', { name: COPY.revokeAqpKey }).click();
  await expect.poll(() => harness.revokeAqpCalls.length).toBe(1);
  // The camera now reads as "never had a key", yet nothing may be issued behind the
  // organiser's back: only an explicit click brings a new key.
  await expect(dialog.getByRole('button', { name: COPY.createAqpKey })).toBeVisible();
  await expect(dialog.locator('svg[width="200"]')).toHaveCount(0);
  await page.waitForTimeout(300);
  expect(harness.createAqpCalls).toHaveLength(0);

  // Closing and reopening the dialog must not issue one either. The key id is gone on the
  // backend, but a key is only issued automatically in the flow that has just created the
  // camera, never inferred from "no key id".
  // `getByRole('dialog')` also matches the manage overlay underneath, so target the key
  // dialog by its title to tell "closed" from "still open".
  const keyDialog = page
    .getByRole('dialog')
    .filter({ has: page.getByText(COPY.qrTitle, { exact: true }) });
  await page.keyboard.press('Escape');
  await expect(keyDialog).toHaveCount(0);
  await page.getByRole('button', { name: COPY.qrAction, exact: true }).click();
  await expect(keyDialog.getByRole('button', { name: COPY.createAqpKey })).toBeVisible();
  await expect(keyDialog.locator('svg[width="200"]')).toHaveCount(0);
  await page.waitForTimeout(300);
  expect(harness.createAqpCalls).toHaveLength(0);
});

test('opening the dialog from the list shows a manual button, not an automatic key, for a camera without one', async ({
  page,
}) => {
  const harness = await installHarness(page, [createdPushCamera]);
  await gotoManage(page);
  await page.getByRole('button', { name: COPY.qrAction, exact: true }).click();

  const dialog = page.getByRole('dialog');
  await expect(dialog.getByRole('button', { name: COPY.createAqpKey })).toBeVisible();
  await expect(dialog.locator('svg[width="200"]')).toHaveCount(0);
  await page.waitForTimeout(300);
  expect(harness.createAqpCalls).toHaveLength(0);

  // An explicit click still issues the key.
  await dialog.getByRole('button', { name: COPY.createAqpKey }).click();
  await expect.poll(() => harness.createAqpCalls.length).toBe(1);
  await expect(dialog.locator('svg[width="200"]')).toBeVisible();
});

