  const overflowPx = await dialog.evaluate((element) => element.scrollWidth - element.clientWidth);
  expect(overflowPx).toBeLessThanOrEqual(0);

  const dialogBox = await dialog.boundingBox();
  const keyBox = await streamKey.boundingBox();
  if (!dialogBox || !keyBox) throw new Error('dialog or stream key has no layout box');
  expect(keyBox.x + keyBox.width).toBeLessThanOrEqual(dialogBox.x + dialogBox.width);
});
