  const hasAdminRole = user?.roles?.includes('ADMIN') ?? false;
  const hasOrganizerRole = user?.roles?.includes('ORGANIZER') ?? false;

  const isUserReferee = user?.roles?.includes('REFEREE') ?? false;
  const isAssignedReferee = isUserReferee && (match.refereeId == null || match.refereeId === user?.id);
  const isClubMatchContext =
    match.contextType === 'CLUB_SOCIAL_MATCH_SESSION' ||
    match.contextType === 'CLUB_STANDALONE_MATCH';
  const isClubMatchPlayer = Boolean(
    user?.id &&
      isClubMatchContext &&
      [match.participant1, match.participant2]
        .flatMap((participant) => participant?.members ?? [])
        .some((member) => member.userId === user.id),
  );
  const canControlLiveMatch = Boolean(
    isClubMatch
      ? match.canEditScore === true
      : hasAdminRole ||
        match.tournament?.createdBy === user?.id ||
        isAssignedReferee ||
        isClubMatchPlayer,
  );
  // Bảng tính điểm chỉ có trong toàn màn hình và chỉ cho người có quyền chấm điểm;
  // thoát toàn màn hình hay mất quyền thì bảng đóng mà không cần reset state.
  const isScorePanelOpen =
    isStageFullscreen && isWideScreen && canControlLiveMatch && isScorePanelRequested;
  const toggleScorePanel = () => setIsScorePanelRequested((open) => !open);
  const closeScorePanel = () => setIsScorePanelRequested(false);

