export interface SportOLivePlayerProps {
…
}

export const SportOLivePlayer: React.FC<SportOLivePlayerProps> = ({
  streamId,
  playbackUrl,
  title,
  aspectRatio = '16/9',
  onStateChange,
  scoreboard,
  overlay,
  onToggleChat,
  isChatOpen = true,
  onToggleScore,
  isScoreOpen = false,
  fullscreenRef,
  fillContainerHeight = false,
  maxHeight,
  onFullscreenChange,
}) => {
  const t = useTranslations('Match');
  const videoRef = useRef<HTMLVideoElement>(null);
  const playerRef = useRef<mpegts.Player | null>(null);
  const hlsRef = useRef<Hls | null>(null);
  const initializePlayerRef = useRef<() => void>(() => {});
  const retryTimeoutRef = useRef<number | null>(null);
  // Tỉ lệ khung hình lấy từ chính luồng phát. Camera sân thường 4:3, ép cứng 16:9
  // tạo viền đen hai bên và làm khung hình nhỏ lại.
  const [videoAspect, setVideoAspect] = useState<number | null>(null);
  const [showControls, setShowControls] = useState(true);
  // Media server thuong phat ca FLV lan HLS cho cung mot stream id, nhung mot
  // endpoint co the tat trong khi endpoint kia van song. Thu FLV truoc vi do tre
  // thap hon; gap loi fatal thi chuyen han sang HLS thay vi retry mai mot endpoint chet.
  //
  // Dung ref chu khong dung state: handler loi goi initializePlayerRef.current() ngay
  // lap tu, luc React con chua render lai, nen state trong closure cu van la false.
  // Ref doc/ghi deu dong bo nen chuyen engine ngay duoc, khong lap vo han.
  const flvFailedRef = useRef(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const retryCountRef = useRef<number>(0);

  const [isMuted, setIsMuted] = useState<boolean>(true);
  const [volume, setVolume] = useState<number>(0.8);
  const [isPlaying, setIsPlaying] = useState<boolean>(false);
  const [hasError, setHasError] = useState<boolean>(false);
  const [isConnecting, setIsConnecting] = useState<boolean>(true);

  // Ảnh chụp màn hình thu nhỏ bị từ chối âm thầm khi luồng live chưa có khung
  // hình nào giải mã được; theo dõi trạng thái media để khoá nút cho tới lúc đó.
  const [videoFrameState, setVideoFrameState] = useState<PictureInPictureVideoState | null>(null);
  const [isPictureInPictureActive, setIsPictureInPictureActive] = useState(false);

  const syncVideoFrameState = useCallback(() => {
    const video = videoRef.current;
    setVideoFrameState(
      video ? { readyState: video.readyState, videoWidth: video.videoWidth } : null,
    );
  }, []);

  // useMemo bắt buộc: resolveStreamUrls trả object mới mỗi lần render. Nếu không,
  // useCallback/useEffect phía dưới thấy dependency đổi mỗi lần → hủy và tạo lại
  // player liên tục, sinh hàng trăm request và làm video nhấp nháy.
  const urls = useMemo(
    () => resolveStreamUrls(streamId, playbackUrl),
    [streamId, playbackUrl],
  );
  const flvUrl = urls?.flvUrl ?? null;
  const hlsUrl = urls?.hlsUrl ?? null;

  const cleanupPlayer = useCallback(() => {
    if (retryTimeoutRef.current !== null) {
…
    }
    if (playerRef.current) {
      try {
        playerRef.current.pause();
        playerRef.current.unload();
        playerRef.current.detachMediaElement();
        playerRef.current.destroy();
      } catch (err) {
        console.warn('[SportO Player] Cleanup warning:', err);
      }
      playerRef.current = null;
    }
    if (hlsRef.current) {
      try {
        hlsRef.current.destroy();
      } catch (err) {
        console.warn('[SportO Player] HLS cleanup warning:', err);
      }
      hlsRef.current = null;
    }
  }, []);

  const initializePlayer = useCallback(() => {
…
    const supportsMseFlv =
      flvUrl !== null && !flvFailedRef.current && mpegts.getFeatureList().mseLivePlayback;
    const supportsNativeHls = video.canPlayType('application/vnd.apple.mpegurl') !== '';

    // Case 1: HTTP-FLV qua mpegts.js — độ trễ thấp nhất, ưu tiên cho PC/Android.
    if (supportsMseFlv) {
      const player = mpegts.createPlayer(
        {
          type: 'flv',
          isLive: true,
          hasAudio: true,
          hasVideo: true,
          url: flvUrl as string,
        },
        {
          enableWorker: true,
          enableStashBuffer: false,
          stashInitialSize: 128,
          lazyLoad: false,
          liveBufferLatencyChasing: true,
          liveBufferLatencyMaxLatency: 1.5,
          liveBufferLatencyMinRemain: 0.3,
          autoCleanupSourceBuffer: true,
          autoCleanupMaxBackwardDuration: 30,
          autoCleanupMinBackwardDuration: 10,
        }
      );

      player.attachMediaElement(video);
      player.load();

      const playPromise = player.play();
      if (playPromise && typeof playPromise.catch === 'function') {
        playPromise.catch(() => {
          // Autoplay bị chặn cho tới khi người dùng bật tiếng; không phải lỗi luồng.
        });
      }

      player.on(mpegts.Events.ERROR, (errorType, errorDetail, errorInfo) => {
        console.error('[SportO Player] mpegts error:', errorType, errorDetail, errorInfo);
        // FLV chet (404, stream tat) nhung HLS co the van song — chuyen ngay sang
        // HLS thay vi retry lai FLV ba lan roi bao loi.
        if (hlsUrl) {
          // Ghi ref truoc khi gọi lại: initializePlayer phải thấy FLV đã chết ngay
          // lượt này, nếu không sẽ tạo player mới trên cùng URL chết và lặp vô hạn.
          flvFailedRef.current = true;
          // Đặt lại hạn mức thử: HLS cần ngân sách retry riêng của nó.
          retryCountRef.current = 0;
          initializePlayerRef.current();
          return;
        }
        retryLater();
      });

      playerRef.current = player;
      return;
    }

    // Case 2: HLS trên trình duyệt không hỗ trợ FLV (iOS/Mac Safari native, hoặc
    // nguồn chỉ có .m3u8 như dạng /index.m3u8 của MediaMTX).
    if (hlsUrl !== null && (Hls.isSupported() || supportsNativeHls)) {
      if (Hls.isSupported()) {
        const hls = new Hls({
          lowLatencyMode: true,
          // Lùi live edge thêm một segment để chịu được dao động mạng; đổi lại tăng độ trễ.
          liveSyncDurationCount: 3,
          backBufferLength: 30,
          enableWorker: true,
        });
        hlsRef.current = hls;
        hls.loadSource(hlsUrl);
        hls.attachMedia(video);
        hls.on(Hls.Events.MANIFEST_PARSED, () => {
          video.play().catch(() => {});
        });
        hls.on(Hls.Events.ERROR, (_event, data) => {
          if (!data.fatal) return;
          console.error('[SportO Player] hls error:', data.type, data.details);
          if (data.type === Hls.ErrorTypes.NETWORK_ERROR) {
            hls.startLoad();
            return;
          }
          if (data.type === Hls.ErrorTypes.MEDIA_ERROR) {
            hls.recoverMediaError();
            return;
          }
          retryLater();
        });

        return;
      }

      video.src = hlsUrl;
      video.load();
      video.play().catch(() => {});
      return;
    }

    setHasError(true);
    setIsConnecting(false);
    onStateChange?.('error');
  }, [urls, flvUrl, hlsUrl, cleanupPlayer, onStateChange]);

  useEffect(() => {
    initializePlayerRef.current = initializePlayer;
    initializePlayer();
    return () => {
      initializePlayerRef.current = () => {};
      cleanupPlayer();
    };
  }, [initializePlayer, cleanupPlayer]);

  const applyVolume = (value: number) => {
    const video = videoRef.current;
    // Không có `video` (chưa gắn ref) vẫn phải cập nhật state, nếu không
    // thanh trượt sẽ kẹt ở vị trí cũ cho tới lần mount sau.
    const clamped = Math.min(1, Math.max(0, value));
    if (video) {
      video.volume = clamped;
      video.muted = clamped === 0;
    }
    setVolume(clamped);
    setIsMuted(clamped === 0);
  };

  // Nút loa chỉ còn 2 trạng thái: đang tắt thì bật lên nửa, đang bật thì tắt.
  const toggleMute = () => {
    applyVolume(isMuted || volume === 0 ? 0.5 : 0);
    revealControls();
  };

  const volumeLabel = isMuted
    ? t('liveStreamMute')
    : volume <= 0.5
      ? t('liveStreamVolumeLow')
      : t('liveStreamVolumeHigh');
…
      <video
…
        onPause={() => {
          // Không có `onPause` thì `isPlaying` chỉ một chiều true → bấm lần hai vẫn
          // gọi `pause()` và không bao giờ phát lại được.
          setIsPlaying(false);
        }}
        // Luồng FLV live hay rớt khung hình, `waiting` bắn liên tục và bật spinner đè
        // lên video đang chạy. Chỉ hiện overlay khi chưa từng có hình nào — lúc đó
        // khán giả thấy màn hình đen nên biết đang tải.
        onWaiting={() => {
          if (!isPlaying) setIsConnecting(true);
          // Luồng live rớt hết khung hình thì `readyState` tụt về 0; nếu không đồng
          // bộ lại, nút cửa sổ nhỏ vẫn sáng dù video không còn khung để bỏ vào.
          syncVideoFrameState();
        }}
      />

      {/* Bảng điểm dán góc trên trái, có khoảng cách padding và pointer-events-none */}
      {scoreboard && (
        <div
          className={`pointer-events-none absolute z-20 transition-all duration-300 ${
            isInFullscreenStage
              ? 'left-3 top-3 sm:left-6 sm:top-6 scale-105 origin-top-left'
              : 'left-1.5 top-1.5 sm:left-3.5 sm:top-3.5'
          }`}
        >
          {scoreboard}
        </div>
      )}

      {/* Lớp đồ họa phát sóng TV Broadcast (H2H, Bracket) */}
      {overlay}

      {/* Thanh điều khiển tự ẩn như YouTube: chỉ hiện khi rê chuột, trừ lúc đang
          hover để người xem không bị mất nút giữa chừng. */}
      <div
        className={`absolute inset-x-0 bottom-0 z-20 flex items-center justify-between gap-2 px-3 py-1 transition-opacity duration-200 ${
          showControls ? 'opacity-100' : 'pointer-events-none opacity-0'
        }`}
      >
        <div className="flex items-center gap-0.5">
          <ControlButton
            label={isPlaying ? t('liveStreamPause') : t('liveStreamPlay')}
…
          >
…
          </ControlButton>
…
        </div>
…
      </div>
…
};

