// Số đo chất lượng luồng cho BTC/admin (huy hiệu Ping/Trễ trên video). Tách khỏi
// SportOLivePlayer.tsx để test Node không phải nạp mpegts.js.

interface TimeRangesLike {
  readonly length: number;
  end(index: number): number;
}

export interface LatencySource {
  readonly currentTime: number;
  readonly seekable: TimeRangesLike;
  readonly buffered: TimeRangesLike;
}

/**
 * Độ trễ so với điểm phát trực tiếp, tính bằng giây. hls.js tự đo (`hls.latency`); FLV
 * (mpegts.js) và HLS gốc của Safari thì lấy mép cuối vùng seekable, không có thì vùng đệm.
 * Trả `null` khi chưa có dữ liệu để đo.
 */
export function liveLatencySeconds(video: LatencySource, hlsLatency?: number | null): number | null {
  if (typeof hlsLatency === 'number' && Number.isFinite(hlsLatency) && hlsLatency > 0) {
    return hlsLatency;
  }
  const ranges = video.seekable.length > 0 ? video.seekable : video.buffered;
  if (ranges.length === 0) return null;
  const lag = ranges.end(ranges.length - 1) - video.currentTime;
  return Number.isFinite(lag) && lag >= 0 ? lag : null;
}

'use client';

import { useEffect, useState, type RefObject } from 'react';
import type Hls from 'hls.js';
import { useTranslations } from 'next-intl';
import { liveLatencySeconds } from './stream-stats';

interface StreamStatsBadgeProps {
  videoRef: RefObject<HTMLVideoElement | null>;
  hlsRef: RefObject<Hls | null>;
  /** Thời gian chờ byte đầu của segment HLS gần nhất (ms), do player ghi khi tải xong segment. */
  pingMsRef: RefObject<number | null>;
}

const REFRESH_MS = 1000;

/** Huy hiệu Ping/Trễ góc trên phải video. Chỉ render cho BTC giải và admin. */
export function StreamStatsBadge({ videoRef, hlsRef, pingMsRef }: StreamStatsBadgeProps) {
  const t = useTranslations('Match');
  const [stats, setStats] = useState<{ pingMs: number | null; latencySec: number | null }>({
    pingMs: null,
    latencySec: null,
  });

  useEffect(() => {
    const timer = window.setInterval(() => {
      const video = videoRef.current;
      setStats({
        pingMs: pingMsRef.current,
        latencySec: video ? liveLatencySeconds(video, hlsRef.current?.latency) : null,
      });
    }, REFRESH_MS);
    return () => window.clearInterval(timer);
  }, [videoRef, hlsRef, pingMsRef]);

  const ping = stats.pingMs === null ? '—' : `${stats.pingMs} ms`;
  const latency = stats.latencySec === null ? '—' : `${stats.latencySec.toFixed(1)} s`;

  return (
    <div
      data-testid="live-stream-stats"
      className="pointer-events-none absolute right-1.5 top-1.5 z-20 rounded-md bg-black/60 px-2 py-1 font-mono text-[11px] leading-none text-white sm:right-3.5 sm:top-3.5"
    >
      {t('liveStreamPing')} {ping} · {t('liveStreamLatency')} {latency}
    </div>
  );
}

