import assert from 'node:assert/strict';
import test from 'node:test';

// @ts-expect-error TS5097 is intentional for this Node-native test entrypoint.
import { liveLatencySeconds } from '../../src/components/player/stream-stats.ts';

const ranges = (...ends: number[]) => ({ length: ends.length, end: (index: number) => ends[index] });

test('prefers the hls.js live latency when it has measured one', () => {
  const video = { currentTime: 10, seekable: ranges(30), buffered: ranges(12) };
  assert.equal(liveLatencySeconds(video, 2.5), 2.5);
});

test('falls back to the seekable live edge, then to the buffer, without hls.js', () => {
  assert.equal(liveLatencySeconds({ currentTime: 10, seekable: ranges(5, 13), buffered: ranges(11) }, 0), 3);
  assert.equal(liveLatencySeconds({ currentTime: 10, seekable: ranges(), buffered: ranges(11.5) }), 1.5);
});

test('reports nothing before media exists or when the edge is behind the playhead', () => {
  assert.equal(liveLatencySeconds({ currentTime: 0, seekable: ranges(), buffered: ranges() }), null);
  assert.equal(liveLatencySeconds({ currentTime: 10, seekable: ranges(9), buffered: ranges() }), null);
});

