    if (pathname === `/api/v1/livestream/matches/${matchId}/control-state`) {
      await fulfillApi(route, { matchId, hasCamera: false, streamStatus: null });
      return;
    }

    await fulfillApi(route, []);
  });

  await page.goto(`/live/${matchId}${options.asOrganizer ? '?scoring=1' : ''}`, {
