      await expect(bracket.getByText(title, { exact: true })).toBeVisible();
    }
    await expect(bracket.locator('[data-overlay-column]')).toHaveCount(4);
    await expect(bracket.getByText('ĐANG DIỄN RA', { exact: true })).toBeVisible();
