    await expect(dialog).toBeVisible();
    await expect(page.locator('[data-overlay="h2h"]')).toHaveCount(0);

    const patched = page.waitForRequest(
      (request) =>
        request.method() === 'PATCH' && request.url().includes('/overlay-visibility'),
    );
    await dialog.getByRole('button', { name: /H2H/ }).click();
    expect((await patched).postDataJSON()).toEqual({ kind: 'H2H', visible: true });
