    await openLivePage(page, { initial: { h2h: true, bracket: false } });

    const h2h = page.locator('[data-overlay="h2h"]');
    await expect(h2h).toBeVisible();
    await page.locator('[data-overlay-close]').click();
    await expect(h2h).toHaveCount(0);
  });

  test('controller turns H2H on through PATCH and the overlay appears from the response', async ({
    page,
  }) => {
    const calls = await openLivePage(page, {
      initial: { h2h: false, bracket: false },
      asOrganizer: true,
    });

    await page.getByRole('button', { name: 'Tính điểm', exact: true }).click();
    const dialog = page.getByRole('dialog');
    await expect(dialog).toBeVisible();
    await expect(page.locator('[data-overlay="h2h"]')).toHaveCount(0);

    const patched = page.waitForRequest(
      (request) =>
        request.method() === 'PATCH' && request.url().includes('/overlay-visibility'),
    );
    await dialog.getByRole('button', { name: /H2H/ }).click();
    expect((await patched).postDataJSON()).toEqual({ kind: 'H2H', visible: true });
    expect(calls.patches).toEqual([{ kind: 'H2H', visible: true }]);

    await expect(page.locator('[data-overlay="h2h"]')).toBeVisible();
  });

