    page,
  }) => {
    const reason = 'Giải vòng bảng chưa hỗ trợ sơ đồ';
    await openLivePage(page, {
      initial: { h2h: false, bracket: false },
      asOrganizer: true,
      content: { ...doubles, bracket: null, bracketReason: reason },
    });

    await page.getByRole('button', { name: 'Tính điểm', exact: true }).click();
    const dialog = page.getByRole('dialog');
    await expect(dialog).toBeVisible();

    await expect(dialog.getByRole('button', { name: /Sơ đồ/ })).toBeDisabled();
