import { readFileSync } from 'node:fs';
import { expect, test, type Page, type Route } from '@playwright/test';

const matchId = 'live-overlay-match';
const tournamentId = 'live-overlay-tournament';
const organizer = {
  id: 'live-overlay-organizer',
  email: 'organizer@example.test',
  fullName: 'Organizer Test',
  roles: ['ORGANIZER'],
  gender: 'MALE',
  isEmailVerified: true,
  profile: { fullName: 'Organizer Test' },
};

interface OverlayContent {
  h2h: { left: { name: string }; right: { name: string } };
  bracket: unknown;
  bracketReason: string | null;
}

// Phản hồi mẫu do Backend sinh (chép nguyên từ test/fixtures/overlay): tứ kết đôi trong giải 16 cặp.
const doubles = JSON.parse(
  readFileSync(
    new URL('../fixtures/overlay/doubles-16-current-qf2.json', import.meta.url),
    'utf8',
  ),
) as OverlayContent;

const pairLabel = `${doubles.h2h.left.name}`;

function buildMatch(flags: { h2h: boolean; bracket: boolean }) {
  return {
    id: matchId,
    groupId: 'live-overlay-group',
    tournamentId,
    status: 'ONGOING',
    roundNumber: 1,
    matchOrder: 1,
    bracketBranch: 'WINNER',
    isBye: false,
    updatedAt: '2026-10-15T02:05:00.000Z',
    startedAt: '2026-10-15T02:05:00.000Z',
    p1SetsWon: 1,
    p2SetsWon: 0,
    revision: 1,
    h2hOverlayVisible: flags.h2h,
    bracketOverlayVisible: flags.bracket,
    participant1Id: `${matchId}-p1`,
    participant2Id: `${matchId}-p2`,
    participant1: {
      id: `${matchId}-p1`,
      teamName: 'Đội Bạn',
      members: [{ userId: `${matchId}-u1`, fullName: 'Nguyễn Văn A' }],
    },
    participant2: {
      id: `${matchId}-p2`,
      teamName: 'Đội Bạc',
      members: [{ userId: `${matchId}-u2`, fullName: 'Trần Văn B' }],
    },
    scoreDetails: { sets: [{ team1Score: 21, team2Score: 14, isFinished: true }] },
    tournament: {
      id: tournamentId,
      name: 'Giải Cầu Lông Kiểm Thử',
      createdBy: organizer.id,
      categoryName: 'Cầu lông',
      categorySlug: 'badminton',
      tournamentConfig: { mode: 'STRICT', maxSets: 3 },
      sportRules: {
        kind: 'BADMINTON',
        mode: 'STRICT',
        scoring: { bestOf: 3, setsToWin: 2, pointsPerSet: 21 },
      },
    },
  };
}

function responseHeaders(route: Route) {
  const requestHeaders = route.request().headers();
  return {
    'access-control-allow-origin': requestHeaders.origin ?? 'http://localhost:3001',
    'access-control-allow-credentials': 'true',
    'access-control-allow-methods': 'GET, POST, PUT, PATCH, DELETE, OPTIONS',
    'access-control-allow-headers':
      requestHeaders['access-control-request-headers'] ?? 'authorization,content-type',
  };
}

async function fulfillApi(route: Route, data: unknown) {
  const headers = responseHeaders(route);
  if (route.request().method() === 'OPTIONS') {
    await route.fulfill({ status: 204, headers });
    return;
  }
  await route.fulfill({ status: 200, headers, json: { data } });
}

interface OverlayState {
  h2h: boolean;
  bracket: boolean;
}

interface OpenOptions {
  initial: OverlayState;
  asOrganizer?: boolean;
  /** Nội dung `/overlay` trả về; mặc định là fixture đôi 16 cặp. */
  content?: OverlayContent;
}

async function openLivePage(page: Page, options: OpenOptions) {
  const state: OverlayState = { ...options.initial };
  const content = options.content ?? doubles;
  const calls = { overlayGet: 0, patches: [] as unknown[] };

  if (options.asOrganizer) {
    await page.addInitScript((user) => {
      localStorage.setItem(
        'auth-storage',
        JSON.stringify({ state: { user, isAuthenticated: true }, version: 0 }),
      );
    }, organizer);
  }

  await page.route('**/api/v1/**', async (route) => {
    const request = route.request();
    const { pathname } = new URL(request.url());

    if (request.method() === 'OPTIONS') {
      await fulfillApi(route, null);
      return;
    }
    if (pathname === `/api/v1/matches/${matchId}`) {
      await fulfillApi(route, buildMatch(state));
      return;
    }
    if (pathname === `/api/v1/matches/${matchId}/overlay`) {
      calls.overlayGet += 1;
      await fulfillApi(route, {
        ...content,
        h2hVisible: state.h2h,
        bracketVisible: state.bracket,
      });
      return;
    }
    if (pathname === `/api/v1/matches/${matchId}/overlay-visibility`) {
      const body = request.postDataJSON() as { kind: 'H2H' | 'BRACKET'; visible: boolean };
      calls.patches.push(body);
      // Backend bật cái này thì tắt cái kia.
      state.h2h = body.kind === 'H2H' && body.visible;
      state.bracket = body.kind === 'BRACKET' && body.visible;
      await fulfillApi(route, {
        id: matchId,
        matchId,
        h2hOverlayVisible: state.h2h,
        bracketOverlayVisible: state.bracket,
      });
      return;
    }
    if (pathname === `/api/v1/matches/${matchId}/comments`) {
      await fulfillApi(route, []);
      return;
    }
    if (pathname === `/api/v1/matches/${matchId}/cheer-count`) {
      await fulfillApi(route, { cheerCount: 0 });
      return;
    }
    if (pathname === `/api/v1/livestream/matches/${matchId}/playback`) {
      await fulfillApi(route, {
        matchId,
        streamStatus: 'LIVE',
        playbackUrl: 'https://media.example.test/live.flv',
        cameraName: 'Sân 1',
        isFeatured: false,
      });
      return;
    }
    if (pathname === `/api/v1/tournaments/${tournamentId}/participants`) {
      await fulfillApi(route, []);
      return;
    }
    if (pathname.endsWith('/users/profile')) {
      await fulfillApi(route, organizer);
      return;
    }
    if (pathname === `/api/v1/livestream/matches/${matchId}/control-state`) {
      await fulfillApi(route, { matchId, hasCamera: false, streamStatus: null });
      return;
    }

    await fulfillApi(route, []);
  });

  await page.goto(`/live/${matchId}${options.asOrganizer ? '?scoring=1' : ''}`, {
    waitUntil: 'domcontentloaded',
  });
  return calls;
}

test.describe('live overlay H2H and Bracket', () => {
  test('viewer sees the H2H the Backend switched on, with the pair names the server built', async ({
    page,
  }) => {
    await openLivePage(page, { initial: { h2h: true, bracket: false } });

    const h2h = page.locator('[data-overlay="h2h"]');
