      await expect(bracket.getByText(title, { exact: true })).toBeVisible();
    }
    await expect(bracket.locator('[data-overlay-column]')).toHaveCount(4);
    await expect(bracket.getByText('ĐANG DIỄN RA', { exact: true })).toBeVisible();
    await expect(page.getByText(/\bQF\d/)).toHaveCount(0);
  });

  test('shows nothing and never calls /overlay while both flags are off', async ({ page }) => {
    const calls = await openLivePage(page, { initial: { h2h: false, bracket: false } });

    await expect(page.getByRole('button', { name: 'Tính điểm', exact: true })).toHaveCount(0);
    await page.waitForTimeout(1500);
    await expect(page.locator('[data-overlay="h2h"]')).toHaveCount(0);
    await expect(page.locator('[data-overlay="bracket"]')).toHaveCount(0);
    expect(calls.overlayGet).toBe(0);
  });

  test('viewer can close the overlay for themselves', async ({ page }) => {
    await openLivePage(page, { initial: { h2h: true, bracket: false } });

    const h2h = page.locator('[data-overlay="h2h"]');
    await expect(h2h).toBeVisible();
    await page.locator('[data-overlay-close]').click();
    await expect(h2h).toHaveCount(0);
  });

  test('controller turns H2H on through PATCH and the overlay appears from the response', async ({
    page,
  }) => {
    const calls = await openLivePage(page, {
      initial: { h2h: false, bracket: false },
      asOrganizer: true,
    });

    await page.getByRole('button', { name: 'Tính điểm', exact: true }).click();
    const dialog = page.getByRole('dialog');
    await expect(dialog).toBeVisible();
    await expect(page.locator('[data-overlay="h2h"]')).toHaveCount(0);

    const patched = page.waitForRequest(
      (request) =>
        request.method() === 'PATCH' && request.url().includes('/overlay-visibility'),
    );
    await dialog.getByRole('button', { name: /H2H/ }).click();
    expect((await patched).postDataJSON()).toEqual({ kind: 'H2H', visible: true });
    expect(calls.patches).toEqual([{ kind: 'H2H', visible: true }]);

    await expect(page.locator('[data-overlay="h2h"]')).toBeVisible();
  });

  test('disables the Bracket button with the server reason but keeps H2H available', async ({
    page,
  }) => {
    const reason = 'Giải vòng bảng chưa hỗ trợ sơ đồ';
    await openLivePage(page, {
      initial: { h2h: false, bracket: false },
      asOrganizer: true,
      content: { ...doubles, bracket: null, bracketReason: reason },
    });

    await page.getByRole('button', { name: 'Tính điểm', exact: true }).click();
    const dialog = page.getByRole('dialog');
    await expect(dialog).toBeVisible();

    await expect(dialog.getByRole('button', { name: /Sơ đồ/ })).toBeDisabled();
    // Modal dựng cả bản desktop lẫn mobile trong DOM; chỉ bản đang hiển thị mới được tính.
    await expect(dialog.locator('p:visible', { hasText: reason }).first()).toBeVisible();
    await expect(dialog.getByRole('button', { name: /H2H/ })).toBeEnabled();
  });
});

test.describe('live overlay on a portrait phone', () => {
  test.use({ viewport: { width: 390, height: 844 } });

  test('the bracket keeps only the live round and the round it feeds', async ({ page }) => {
