  const mismatched =
    (restriction === 'MALE' && genders.some((gender) => gender !== 'MALE')) ||
    (restriction === 'FEMALE' &&
      genders.some((gender) => gender !== 'FEMALE')) ||
    (restriction === 'MIXED' &&
