  private async persistImportRows(
    tx: AppTx,
    context: {
      tournamentId: string;
      managerUserId: string;
      tournament: typeof schema.tournaments.$inferSelect;
      divisionId?: string;
      rows: ImportPersistRow[];
      strippedResponseKeys: readonly string[];
    },
  ): Promise<{
    participants: (typeof schema.tournamentParticipants.$inferSelect)[];
    linkedAccountNotifications: Array<{
      rosterId: string;
      userId: string;
      status: 'COMPLETE' | 'PENDING_APPROVAL';
      divisionId: string | null;
    }>;
  }> {
    const {
      tournamentId,
      managerUserId,
      tournament,
      divisionId,
      rows,
      strippedResponseKeys,
    } = context;
    const entryFeeAtRegistration = (
      await this.tournamentPaymentRepository.resolveDivisionEntryFee(
        tx,
        tournament,
        divisionId,
      )
    ).toFixed(2);
    // Seeds continue after the division's highest seed. The advisory lock is the
    // one assignNextAvailableSeed takes, so concurrent seeding cannot read the same max.
    let seedBase = 0;
    if (rows.length > 0) {
      await tx.execute(
        sql`SELECT pg_advisory_xact_lock(hashtext(${`tournament-seeding:${tournamentId}`}))`,
      );
      const [highestSeed] = await tx
        .select({
          maxSeed: sql<
            number | null
          >`max(${schema.tournamentParticipants.seed})`,
        })
        .from(schema.tournamentParticipants)
        .where(
          and(
            eq(schema.tournamentParticipants.tournamentId, tournamentId),
            divisionId
              ? eq(
                  schema.tournamentParticipants.tournamentDivisionId,
                  divisionId,
                )
              : isNull(schema.tournamentParticipants.tournamentDivisionId),
            sql`${schema.tournamentParticipants.seed} IS NOT NULL`,
          ),
        );
      seedBase = Number(highestSeed?.maxSeed ?? 0);
    }
    const participants: (typeof schema.tournamentParticipants.$inferSelect)[] =
      [];
    const linkedAccountNotifications: Array<{
      rosterId: string;
      userId: string;
      status: 'COMPLETE' | 'PENDING_APPROVAL';
      divisionId: string | null;
    }> = [];

    for (const [index, row] of rows.entries()) {
      const teamStatus =
        row.autoApprove && (row.isPaid ?? true)
          ? 'COMPLETE'
          : 'PENDING_APPROVAL';

      const customResponses = { ...(row.customResponses ?? {}) };
      for (const key of strippedResponseKeys) {
        delete customResponses[key];
      }
…
    }
