import type { TournamentParticipant } from '@/types/tournament';

type RosterMember = TournamentParticipant['members'][number];

/** The slice of a participant these helpers read. `footballTeamId` marks a club registration. */
export interface RegistrationIdentitySource {
  teamName?: string | null;
  members?: RosterMember[] | null;
  registeredBy?: { id: string } | null;
  customResponses?: Record<string, unknown> | null;
  footballTeamId?: string | null;
}

export interface RegistrationPerson {
  key: string;
  /** `null` for an athlete without a SportO account. */
  userId: string | null;
  fullName: string | null;
  /** Real avatar of an account holder; `null` means the UI draws the initials of the name. */
  avatarUrl: string | null;
  email: string | null;
  phoneNumber: string | null;
  /** True only for a roster member backed by a real (non-virtual) SportO account. */
  hasAccount: boolean;
  isLeader: boolean;
  /** The roster entry (ELO, account-link status); `null` for an athlete without an account. */
  member: RosterMember | null;
}

export interface ResolveRegistrationPeopleOptions {
  /**
   * `public` never reads `customResponses` (organizer-only contact data) and never marks a leader.
   * Default: `organizer`.
   */
  audience?: 'organizer' | 'public';
}

export interface RegistrationResponseEntry {
  key: string;
  value: unknown;
  /** A system key with a translated label (see `KNOWN_RESPONSE_KEYS`). */
  known: boolean;
  /** Readable fallback for an unknown key; known keys are labelled by the caller's translations. */
  label: string;
}

/** Sources written by the backend (`IMPORT_SOURCES` plus the organizer's direct add). */
export const REGISTRATION_SOURCES = [
  'ORGANIZER_DIRECT',
  'MANUAL_EMAIL',
  'EXCEL',
  'AI_EXCEL',
  'GOOGLE_FORM',
] as const;

/** System keys in `customResponses` that have a translated label. */
export const KNOWN_RESPONSE_KEYS = [
  'notes',
  'note',
  'is_wildcard',
  'sourceFileName',
  'sourceRowIndex',
  'sourceSheetName',
] as const;

/** Shown elsewhere in the modal (source line, athlete rows), so they are not repeated as answers. */
const HIDDEN_RESPONSE_KEYS: ReadonlySet<string> = new Set([
  'importedFrom',
  'player1Name',
  'player1Email',
  'player1Phone',
  'player2Name',
  'player2Email',
  'player2Phone',
  // Backend pair slots for a pair holding a guest (doubles-pair-member.ts); null = guest.
  'player1UserId',
  'player2UserId',
]);

const KNOWN_RESPONSE_KEY_SET: ReadonlySet<string> = new Set(KNOWN_RESPONSE_KEYS);

interface GuestSlot {
  /** `null` when the name was never stored (see `readGuestSlots`). */
  name: string | null;
  email: string | null;
  phone: string | null;
}

function text(value: unknown): string | null {
  return typeof value === 'string' && value.trim() ? value.trim() : null;
}

function normalize(value: string | null | undefined): string {
  return (value ?? '').trim().toLowerCase();
}

function toMemberPerson(member: RosterMember, index: number, organizerView: boolean): RegistrationPerson {
  const hasAccount = member.isMock !== true && Boolean(member.userId);
  return {
    key: member.userId || `member-${index}`,
    userId: member.userId || null,
    fullName: member.fullName ?? null,
    avatarUrl: hasAccount ? (member.avatarUrl ?? null) : null,
    email: organizerView ? (member.email ?? null) : null,
    phoneNumber: organizerView ? (member.phoneNumber ?? null) : null,
    hasAccount,
    isLeader: false,
    member,
  };
}

/**
 * Who the organizer typed in. Organizer view reads the import metadata: the backend keeps
 * `player2Name` and the contact fields, but NOT player 1's name. `teamName` is the athlete's name
 * for a direct add (`teamName = name`) and for an import without a partner, yet for a pair import
 * it can be a team label ("Đội Linh Hoạt"), so there player 1 stays unnamed rather than be guessed.
 * Public view only has the team name.
 */
function readGuestSlots(
  participant: RegistrationIdentitySource,
  responses: Record<string, unknown> | null,
  organizerView: boolean,
): GuestSlot[] {
  const teamName = text(participant.teamName);
  if (!organizerView) {
    return (teamName ?? '')
      .split(/\s*[/&]\s*/)
      .map((name) => name.trim())
      .filter(Boolean)
      .map((name) => ({ name, email: null, phone: null }));
  }

  const slots: GuestSlot[] = [];
  const source = getRegistrationSource(responses);
  const player2Name = text(responses?.player2Name);
  const teamNameIsAthlete = source === 'ORGANIZER_DIRECT' || player2Name === null;
  const player1Name = text(responses?.player1Name) ?? (teamNameIsAthlete ? teamName : null);
  if (player1Name || (source !== null && player2Name !== null)) {
    slots.push({
      name: player1Name,
      email: text(responses?.player1Email),
      phone: text(responses?.player1Phone),
    });
  }
  if (player2Name) {
    slots.push({
      name: player2Name,
      email: text(responses?.player2Email),
      phone: text(responses?.player2Phone),
    });
  }
  return slots;
}

/** Athletes the organizer named who have no roster entry (no matched SportO account). */
function readMissingGuests(
  participant: RegistrationIdentitySource,
  responses: Record<string, unknown> | null,
  members: RosterMember[],
  organizerView: boolean,
): RegistrationPerson[] {
  const slots = readGuestSlots(participant, responses, organizerView);
  if (members.length >= slots.length) return [];

  const memberEmails = new Set(members.map((member) => normalize(member.email)).filter(Boolean));
  const memberNames = new Set(members.map((member) => normalize(member.fullName)).filter(Boolean));

  return slots
    .filter((slot) => {
      const matchedByEmail = slot.email !== null && memberEmails.has(normalize(slot.email));
      return !matchedByEmail && !(slot.name !== null && memberNames.has(normalize(slot.name)));
    })
    .map((slot, index) => ({
      key: `guest-${index}`,
      userId: null,
      fullName: slot.name,
      avatarUrl: null,
      email: slot.email,
      phoneNumber: slot.phone,
      hasAccount: false,
      isLeader: false,
      member: null,
    }));
}

/**
 * The athletes of a registration, in display order.
 *
 * - Roster members come first; an athlete without an account follows as a guest (initials avatar).
 * - `registeredBy` is NEVER an athlete: for an organizer-created registration it is the organizer.
 * - A leader exists only for a self-registered team of two or more whose registrant is a member
 *   with an account. Organizer-created registrations (any `importedFrom`) have no leader: the
 *   backend marks every roster member `MAIN`, so the role says nothing about who leads.
 * - A club registration (`footballTeamId`) never turns the club name into an athlete.
 */
export function resolveRegistrationPeople(
  participant: RegistrationIdentitySource,
  options: ResolveRegistrationPeopleOptions = {},
): RegistrationPerson[] {
  const organizerView = options.audience !== 'public';
  const responses = organizerView ? (participant.customResponses ?? null) : null;
  const members = participant.members ?? [];
  const people = members.map((member, index) => toMemberPerson(member, index, organizerView));

  if (!participant.footballTeamId) {
    people.push(...readMissingGuests(participant, responses, members, organizerView));
  }

  const registrantId = participant.registeredBy?.id;
  if (organizerView && people.length > 1 && registrantId && !getRegistrationSource(responses)) {
    const leader = people.find((person) => person.hasAccount && person.userId === registrantId);
    if (leader) leader.isLeader = true;
  }

  return people;
}

/** The backend's record of where an organizer-created registration came from, if any. */
export function getRegistrationSource(
  customResponses: Record<string, unknown> | null | undefined,
): string | null {
  return text(customResponses?.importedFrom);
}

/**
 * One athlete waiting for a doubles partner. An entry the organizer added or
 * imported always names athlete 1, and a second athlete when it names athlete
 * 2; other entries hold exactly their rosters. Mirrors backend
 * `countParticipantMembers` / `resolveSingleMember`.
 */
export function holdsSingleAthlete(
  rosterCount: number,
  customResponses: Record<string, unknown> | null | undefined,
): boolean {
  const source = getRegistrationSource(customResponses);
  if (!REGISTRATION_SOURCES.some((known) => known === source)) return rosterCount === 1;
  const namesAthlete2 = Boolean(
    text(customResponses?.player2Name) || text(customResponses?.player2Email),
  );
  return Math.max(rosterCount, namesAthlete2 ? 2 : 1) === 1;
}

/** `shirtSize` / `preferred_hand` / `club-name` become `Shirt size` / `Preferred hand` / `Club name`. */
export function humanizeResponseKey(key: string): string {
  const words = key
    .replace(/[_-]+/g, ' ')
    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
  return words ? words.charAt(0).toUpperCase() + words.slice(1) : '';
}

function isEmptyResponse(value: unknown): boolean {
  if (value === null || value === undefined) return true;
  if (typeof value === 'string') return value.trim() === '';
  return Array.isArray(value) && value.length === 0;
}

/**
 * Answers that are not form fields and not shown elsewhere in the modal: system keys with a
 * translated label, and unknown keys with a readable fallback label. Never the raw key as a label
 * for a key the app knows.
 */
export function classifyCustomResponses(
  customResponses: Record<string, unknown> | null | undefined,
  formFieldIds: readonly string[],
): RegistrationResponseEntry[] {
  if (!customResponses) return [];
  const formIds = new Set(formFieldIds);

  return Object.entries(customResponses)
    .filter(([key, value]) => !formIds.has(key) && !HIDDEN_RESPONSE_KEYS.has(key) && !isEmptyResponse(value))
    .map(([key, value]) => ({
      key,
      value,
      known: KNOWN_RESPONSE_KEY_SET.has(key),
      label: humanizeResponseKey(key),
    }));
}

