import assert from 'node:assert/strict';
import test from 'node:test';

import {
  classifyCustomResponses,
  getRegistrationSource,
  humanizeResponseKey,
  resolveRegistrationPeople,
  type RegistrationIdentitySource,
} from '@/features/tournaments/registration-identity';

const ORGANIZER = { id: 'organizer-1', fullName: 'Nguyễn Minh Danh' };

function member(
  userId: string,
  fullName: string,
  extra: Partial<NonNullable<RegistrationIdentitySource['members']>[number]> = {},
) {
  return {
    userId,
    fullName,
    avatarUrl: null,
    role: 'MAIN',
    elo: { eloPoints: 1000, tierName: 'Bronze' },
    ...extra,
  };
}

const names = (people: { fullName: string | null }[]) => people.map((person) => person.fullName);

test('a participant the organizer added by name shows that athlete, never the organizer', () => {
  const people = resolveRegistrationPeople({
    teamName: 'da',
    members: [],
    registeredBy: ORGANIZER,
    customResponses: { importedFrom: 'ORGANIZER_DIRECT' },
  });

  assert.deepEqual(names(people), ['da']);
  assert.equal(people[0].userId, null);
  assert.equal(people[0].hasAccount, false);
  assert.equal(people[0].avatarUrl, null);
  assert.equal(people[0].isLeader, false);
  assert.equal(people.some((person) => person.userId === ORGANIZER.id), false);
});

test('the contact email of a guest is kept for the organizer view', () => {
  const [guest] = resolveRegistrationPeople({
    teamName: 'da',
    members: [],
    registeredBy: ORGANIZER,
    customResponses: { importedFrom: 'ORGANIZER_DIRECT', player1Email: 'da@example.test' },
  });

  assert.equal(guest.email, 'da@example.test');
});

test('a self-registered pair names only the registrant as leader', () => {
  const people = resolveRegistrationPeople({
    teamName: 'An & Bình',
    members: [member('u-an', 'An'), member('u-binh', 'Bình')],
    registeredBy: { id: 'u-an' },
    customResponses: null,
  });

  assert.deepEqual(
    people.map((person) => [person.fullName, person.isLeader]),
    [
      ['An', true],
      ['Bình', false],
    ],
  );
});

test('a pair the organizer formed has no leader even though both are MAIN', () => {
  const people = resolveRegistrationPeople({
    teamName: 'An / Bình',
    members: [member('u-an', 'An'), member('u-binh', 'Bình')],
    registeredBy: ORGANIZER,
    customResponses: null,
  });

  assert.equal(people.length, 2);
  assert.equal(people.some((person) => person.isLeader), false);
});

test('an imported pair has no leader even when the registrant is one of the members', () => {
  const people = resolveRegistrationPeople({
    teamName: 'An / Bình',
    members: [member('u-an', 'An'), member('u-binh', 'Bình')],
    registeredBy: { id: 'u-an' },
    customResponses: { importedFrom: 'EXCEL' },
  });

  assert.equal(people.some((person) => person.isLeader), false);
});

test('a single athlete is never a leader: there is no team to lead', () => {
  const [only] = resolveRegistrationPeople({
    teamName: 'An',
    members: [member('u-an', 'An')],
    registeredBy: { id: 'u-an' },
    customResponses: null,
  });

  assert.equal(only.isLeader, false);
});

test('the organizer who registers as an athlete in a pair is still the leader', () => {
  const people = resolveRegistrationPeople({
    teamName: 'Danh & Bình',
    members: [member(ORGANIZER.id, 'Danh'), member('u-binh', 'Bình')],
    registeredBy: ORGANIZER,
    customResponses: null,
  });

  assert.deepEqual(
    people.map((person) => [person.fullName, person.isLeader]),
    [
      ['Danh', true],
      ['Bình', false],
    ],
  );
});

test('a roster member with an account keeps the real avatar and the roster entry', () => {
  const rosterEntry = member('u-an', 'An', { avatarUrl: 'https://cdn.example.test/an.png' });
  const [person] = resolveRegistrationPeople({
    teamName: 'An',
    members: [rosterEntry],
    registeredBy: { id: 'u-an' },
  });

  assert.equal(person.hasAccount, true);
  assert.equal(person.userId, 'u-an');
  assert.equal(person.avatarUrl, 'https://cdn.example.test/an.png');
  assert.equal(person.member, rosterEntry);
});

test('a virtual athlete counts as having no account and gets no avatar', () => {
  const [person] = resolveRegistrationPeople({
    teamName: 'Bot',
    members: [member('u-bot', 'Bot', { isMock: true, avatarUrl: 'https://cdn.example.test/bot.png' })],
  });

  assert.equal(person.hasAccount, false);
  assert.equal(person.avatarUrl, null);
});

test('a pair with one matched account and one unmatched contact lists both, not the team name', () => {
  const people = resolveRegistrationPeople({
    teamName: 'Đội Linh Hoạt',
    members: [member('u-an', 'An', { email: 'an@example.test' })],
    registeredBy: { id: 'u-an' },
    customResponses: {
      importedFrom: 'EXCEL',
      player1Email: 'an@example.test',
      player2Name: 'Bình',
      player2Email: 'binh@example.test',
    },
  });

  assert.deepEqual(names(people), ['An', 'Bình']);
  assert.equal(people[0].hasAccount, true);
  assert.equal(people[1].hasAccount, false);
  assert.equal(people[1].email, 'binh@example.test');
});

test('an Excel pair without a stored player 1 name does not pass the team label off as an athlete', () => {
  const people = resolveRegistrationPeople({
    teamName: 'Đội Linh Hoạt',
    members: [],
    registeredBy: ORGANIZER,
    customResponses: { importedFrom: 'EXCEL', player1Email: 'minh@example.test', player2Name: 'Lan' },
  });

  assert.deepEqual(names(people), [null, 'Lan']);
  assert.equal(people[0].email, 'minh@example.test');
  assert.equal(people.every((person) => !person.hasAccount), true);
});

test('an Excel pair uses player 1 name when the backend stored it', () => {
  const people = resolveRegistrationPeople({
    teamName: 'Đội Linh Hoạt',
    members: [],
    registeredBy: ORGANIZER,
    customResponses: { importedFrom: 'EXCEL', player1Name: 'Minh', player2Name: 'Lan' },
  });

  assert.deepEqual(names(people), ['Minh', 'Lan']);
});

test('an Excel single (no player 2) takes the team name as the athlete', () => {
  const people = resolveRegistrationPeople({
    teamName: 'Minh',
    members: [],
    registeredBy: ORGANIZER,
    customResponses: { importedFrom: 'EXCEL', player1Email: 'minh@example.test' },
  });

  assert.deepEqual(names(people), ['Minh']);
  assert.equal(people[0].email, 'minh@example.test');
});

test('an athlete added by choosing an account is not duplicated as a guest from the team name', () => {
  const people = resolveRegistrationPeople({
    teamName: 'An',
    members: [member('u-an', 'An')],
    registeredBy: ORGANIZER,
    customResponses: null,
  });

  assert.deepEqual(names(people), ['An']);
});

test('a football club registration never turns the club name into an athlete', () => {
  const people = resolveRegistrationPeople({
    teamName: 'CLB Sông Hàn',
    footballTeamId: 'club-1',
    members: [],
    registeredBy: ORGANIZER,
    customResponses: { importedFrom: 'ORGANIZER_DIRECT' },
  });

  assert.deepEqual(people, []);
});

test('missing data is handled without throwing', () => {
  assert.deepEqual(resolveRegistrationPeople({ teamName: '', members: null, customResponses: null }), []);
  assert.deepEqual(resolveRegistrationPeople({}), []);
  assert.deepEqual(resolveRegistrationPeople({ teamName: '   ', members: [], registeredBy: ORGANIZER }), []);
});

test('the public view reads names from the team name only and ignores organizer-only data', () => {
  const people = resolveRegistrationPeople(
    {
      teamName: 'Minh / Lan',
      members: [],
      registeredBy: ORGANIZER,
      customResponses: {
        importedFrom: 'EXCEL',
        player1Email: 'minh@example.test',
        player2Name: 'Khác',
        player2Phone: '0900000000',
      },
    },
    { audience: 'public' },
  );

  assert.deepEqual(names(people), ['Minh', 'Lan']);
  assert.equal(people.every((person) => person.email === null && person.phoneNumber === null), true);
  assert.equal(people.some((person) => person.isLeader), false);
});

test('the public view keeps a roster member and adds the missing partner from the team name', () => {
  const people = resolveRegistrationPeople(
    {
      teamName: 'An / Bình',
      members: [member('u-an', 'An')],
      registeredBy: { id: 'u-an' },
    },
    { audience: 'public' },
  );

  assert.deepEqual(names(people), ['An', 'Bình']);
  assert.equal(people[0].isLeader, false);
  assert.equal(people[1].hasAccount, false);
});

test('getRegistrationSource returns the trimmed import source and ignores anything else', () => {
  assert.equal(getRegistrationSource({ importedFrom: ' ORGANIZER_DIRECT ' }), 'ORGANIZER_DIRECT');
  assert.equal(getRegistrationSource({ importedFrom: 'EXCEL' }), 'EXCEL');
