import { test, expect, type APIRequestContext, type APIResponse } from '@playwright/test';

// Full doubles flow against the real Backend + Postgres (fullstack-e2e): quick
// tournament default, organizer pairing without gender checks, doubles bracket.
const API = process.env.NEXT_PUBLIC_API_URL || process.env.NEXT_API_URL || 'http://localhost:3000/api/v1';

async function json<T>(response: APIResponse): Promise<T> {
  const body = (await response.json()) as { data?: T } & T;
  return (body && typeof body === 'object' && 'data' in body ? body.data : body) as T;
}

async function organizerHeaders(request: APIRequestContext) {
  const login = await request.post(`${API}/auth/login`, {
    data: { email: 'admin1@gmail.com', password: '123456' },
  });
  expect(login.ok(), await login.text()).toBe(true);
  const token = /accessToken=([^;]+)/.exec(login.headers()['set-cookie'] ?? '')?.[1];
  expect(token, 'login must set the accessToken cookie').toBeTruthy();
  return { Authorization: `Bearer ${token}` };
}

type Division = { id: string; name: string; matchType: string; genderRestriction: string | null };
type Participant = { id: string; teamStatus: string };

test.describe.serial('organizer doubles: default division, gender-free pairing, bracket', () => {
  test.setTimeout(120_000);

  test('quick tournament → Đôi Linh Hoạt → mock singles → random pairs → doubles bracket', async ({ request }) => {
    const headers = await organizerHeaders(request);

    const created = await request.post(`${API}/tournaments/lite`, {
      headers,
      data: { name: `E2E doubles ${Date.now()}`, sport: 'badminton', divisions: [] },
    });
    expect(created.ok(), await created.text()).toBe(true);
    const tournamentId = (await json<{ id: string }>(created)).id;

    // Quick create with no format: one open doubles division.
    const divisions = await json<Division[]>(
      await request.get(`${API}/tournaments/${tournamentId}/divisions`, { headers }),
    );
    expect(divisions.map(({ name, matchType, genderRestriction }) => ({ name, matchType, genderRestriction })))
      .toEqual([{ name: 'Đôi Linh Hoạt', matchType: 'DOUBLES', genderRestriction: null }]);
    const divisionId = divisions[0].id;

    // Four virtual athletes waiting for a partner.
    const seeded = await request.post(`${API}/tournaments/${tournamentId}/mock-participants`, {
      headers,
      data: { names: ['Ảo 1', 'Ảo 2', 'Ảo 3', 'Ảo 4'], divisionId, pairingMode: 'INDIVIDUAL_WAITING' },
    });
    expect(seeded.ok(), await seeded.text()).toBe(true);

    // Singles waiting for a partner are not teams: no bracket yet.
    const early = await request.post(`${API}/tournaments/${tournamentId}/generate-bracket`, {
      headers,
      data: { divisionId },
    });
    expect(early.status(), await early.text()).toBe(400);

    // Random pairing pairs all four (no gender on the virtual accounts).
    const paired = await request.post(`${API}/tournaments/${tournamentId}/pairing/generate`, {
      headers,
      data: { strategy: 'RANDOM' },
    });
    expect(paired.ok(), await paired.text()).toBe(true);
    expect((await json<{ paired: unknown[] }>(paired)).paired).toHaveLength(2);

    const bracket = await request.post(`${API}/tournaments/${tournamentId}/generate-bracket`, {
      headers,
      data: { divisionId },
    });
    expect(bracket.ok(), await bracket.text()).toBe(true);

    // The bracket holds exactly the two pairs: one final, no withdrawn single.
    const participants = await json<Participant[]>(
      await request.get(`${API}/tournaments/${tournamentId}/divisions/${divisionId}/participants`, { headers }),
    );
    const teams = participants.filter((participant) => participant.teamStatus === 'COMPLETE');
    expect(teams).toHaveLength(2);
    const full = await json<{ matches?: Array<{ participant1Id: string | null; participant2Id: string | null }> }>(
      await request.get(`${API}/tournaments/${tournamentId}/bracket?divisionId=${divisionId}`, { headers }),
    );
    const seatedIds = new Set(
      (full.matches ?? []).flatMap((match) => [match.participant1Id, match.participant2Id]).filter(Boolean),
    );
    expect([...seatedIds].sort()).toEqual(teams.map((team) => team.id).sort());
  });

  test('random pairing in a mixed doubles division ignores gender', async ({ request }) => {
    const headers = await organizerHeaders(request);
    const created = await request.post(`${API}/tournaments/lite`, {
      headers,
      data: { name: `E2E mixed ${Date.now()}`, sport: 'badminton', divisions: [] },
    });
    expect(created.ok(), await created.text()).toBe(true);
    const tournamentId = (await json<{ id: string }>(created)).id;

    const division = await request.post(`${API}/tournaments/${tournamentId}/divisions`, {
      headers,
      data: { name: 'Đôi Nam Nữ', matchType: 'MIXED_DOUBLES', genderRestriction: 'MIXED' },
    });
    expect(division.ok(), await division.text()).toBe(true);
    const divisionId = (await json<{ id: string }>(division)).id;

    const seeded = await request.post(`${API}/tournaments/${tournamentId}/mock-participants`, {
      headers,
      data: { names: ['Ảo A', 'Ảo B'], divisionId, pairingMode: 'INDIVIDUAL_WAITING' },
    });
    expect(seeded.ok(), await seeded.text()).toBe(true);

    // Before 2026-10-16 this failed: the accounts have no gender on file.
    const paired = await request.post(`${API}/tournaments/${tournamentId}/pairing/generate`, {
      headers,
      data: { strategy: 'RANDOM' },
    });
    expect(paired.ok(), await paired.text()).toBe(true);
    expect((await json<{ paired: unknown[] }>(paired)).paired).toHaveLength(1);
  });
});

