'use client';

import { useEffect, useRef, useState } from 'react';
import {
  HEADER_AUTO_HIDE_ENTRY_DELAY_MS,
  nextHeaderHidden,
  type HeaderScrollState,
} from '@/utils/header-auto-hide';

interface HiddenState {
  /** Tuyến mà trạng thái này thuộc về: đổi trang thì tự về "hiện" mà không cần setState trong effect. */
  routeKey: string;
  hidden: boolean;
}

/**
 * Khớp `max-md` của Header và ngưỡng `max-width: 767.98px` trong `globals.css`. Ngoài điện thoại header
 * không bao giờ ẩn, nên hook cũng không được tự cuộn trang (nếu không trang sẽ nhảy dưới header đứng yên).
 */
const PHONE_QUERY = '(max-width: 767.98px)';

/**
 * `true` khi header phải trượt ẩn. Chỉ có tác dụng khi `enabled`. Đồng bộ cờ `data-header-hidden`
 * lên <html> để các phần tử sticky bám dưới header (biến `--app-header-height`) đi theo.
 *
 * Quy tắc: vào trang ⇒ đợi một chút rồi tự ẩn; kéo xuống ⇒ ẩn; kéo lên ⇒ hiện.
 * `forceVisible` (menu mở, tiêu điểm bàn phím) thắng tất cả.
 *
 * Header là phần tử sticky nằm trong luồng nên chỉ trượt nó đi sẽ để lại một dải trống ở đầu trang.
 * Vì vậy khi tự ẩn lúc vào trang, trang cũng được cuộn đúng chiều cao header (có hoạt cảnh) để nội dung
 * lấp chỗ đó. Trang quá ngắn không đủ chỗ cuộn thì giữ header nguyên (ẩn rồi chỉ còn dải trống là vô ích).
 */
export function useHeaderAutoHide(routeKey: string, enabled: boolean, forceVisible: boolean): boolean {
  const [state, setState] = useState<HiddenState>({ routeKey, hidden: false });
