  const scrollRef = useRef<HeaderScrollState>({ hidden: false, lastY: 0 });
  // Người dùng đã tự cuộn: không để bộ hẹn giờ lúc vào trang ghi đè quyết định của họ.
  const decidedRef = useRef(false);

  useEffect(() => {
    if (!enabled) return;
    scrollRef.current = { hidden: false, lastY: window.scrollY };
    decidedRef.current = false;

    const setHidden = (next: boolean) =>
      setState((current) =>
        current.routeKey === routeKey && current.hidden === next ? current : { routeKey, hidden: next },
      );

    const entryTimer = window.setTimeout(() => {
      if (decidedRef.current || !window.matchMedia(PHONE_QUERY).matches) return;
      const headerHeight = Math.ceil(document.querySelector('header')?.getBoundingClientRect().height ?? 0);
      const scrollRange = document.documentElement.scrollHeight - window.innerHeight;
      if (headerHeight === 0 || scrollRange < headerHeight) return;

      scrollRef.current = { hidden: true, lastY: window.scrollY };
      setHidden(true);
      if (window.scrollY === 0) {
