    let frame = 0;
    const onScroll = () => {
      if (frame) return;
      frame = window.requestAnimationFrame(() => {
        frame = 0;
        if (!window.matchMedia(PHONE_QUERY).matches) return;
        const next = nextHeaderHidden(scrollRef.current, window.scrollY);
        if (next === scrollRef.current) return;
        // Đoạn cuộn do chính hook thực hiện lúc vào trang cũng đi qua đây nhưng vẫn là "kéo xuống".
        if (next.hidden !== scrollRef.current.hidden) decidedRef.current = true;
        scrollRef.current = next;
        setHidden(next.hidden);
      });
    };

    window.addEventListener('scroll', onScroll, { passive: true });
