import { expect, test, type Page, type Route } from '@playwright/test';
import {
  HEADER_AUTO_HIDE_ENTRY_DELAY_MS,
  nextHeaderHidden,
  shouldAutoHideHeader,
} from '../../src/utils/header-auto-hide';
import { openManage } from './support/organizer-manage';

// Change: changes/live-mobile-chat-fit-header-autohide-20261014 (AC-4, AC-5, AC-6); luật "mọi trang trừ nav chính": changes/header-autohide-all-pages-20261015.

test.describe('header auto-hide: pure rules', () => {
  test('TC-FEAT-HDR-01 every page opts in except the main navigation pages', () => {
    const fixedHeader = ['/', '/home', '/tournaments', '/matches', '/leaderboard', '/tournaments/', null, undefined];
    const autoHide = [
      '/tournaments/abc',
      '/tournaments/abc/results',
      '/live/m1',
      '/users/u1',
      '/series/my-series',
      '/communities',
      '/communities/c1',
      '/organizer/tournaments',
      '/organizer/tournaments/abc/manage',
      '/profile',
      '/notifications',
      '/payments/checkout',
    ];
    for (const route of fixedHeader) expect(shouldAutoHideHeader(route), String(route)).toBe(false);
    for (const route of autoHide) expect(shouldAutoHideHeader(route), route).toBe(true);
  });

  test('TC-FEAT-HDR-02 scrolling down hides, scrolling up shows, small moves are ignored', () => {
    let state = { hidden: false, lastY: 0 };
    state = nextHeaderHidden(state, 300);
    expect(state.hidden).toBe(true);
    // Rung nhẹ dưới ngưỡng: giữ nguyên trạng thái và mốc cũ.
    expect(nextHeaderHidden(state, 303)).toEqual(state);
    state = nextHeaderHidden(state, 250);
    expect(state.hidden).toBe(false);
    state = nextHeaderHidden(state, 400);
    expect(state.hidden).toBe(true);
    // Cuộn nảy iOS (y âm) tính là đang ở đỉnh, kéo lên ⇒ hiện.
    state = nextHeaderHidden(state, -30);
    expect(state.hidden).toBe(false);
    expect(state.lastY).toBe(0);
  });
});

async function headerBounds(page: Page) {
  return page.evaluate(() => {
    const rect = document.querySelector('header')!.getBoundingClientRect();
    return { top: Math.round(rect.top), bottom: Math.round(rect.bottom) };
  });
}

const headerIsHidden = async (page: Page) => (await headerBounds(page)).bottom <= 1;
const headerIsShown = async (page: Page) => (await headerBounds(page)).top >= -1;

test.describe('header auto-hide: phone on a back-button page', () => {
  test.use({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });

  test('TC-FEAT-HDR-04 header slides away by itself on entry, then follows the scroll direction', async ({ page }) => {
    await openManage(page, { tab: 'overview' });
    await expect(page.locator('header')).toBeVisible();
    expect(await page.evaluate(() => document.documentElement.scrollHeight - window.innerHeight)).toBeGreaterThan(400);

    const headerHeight = await page.evaluate(() => document.querySelector('header')!.offsetHeight);

    // Vào trang: header tự trượt ẩn trước khi người dùng cuộn.
    await expect.poll(() => headerIsHidden(page), { timeout: HEADER_AUTO_HIDE_ENTRY_DELAY_MS + 3000 }).toBe(true);

    // Nội dung lấp chỗ header: trang cuộn đúng chiều cao header nên nút quay lại (vốn nằm dưới header) lên sát đỉnh,
    // không để lại dải trống rộng bằng header.
    await expect
      .poll(() => page.getByText('Quay lại', { exact: true }).first().evaluate((el) => Math.round(el.getBoundingClientRect().top)))
      .toBeLessThan(headerHeight - 10);

    // Kéo xuống xem thêm: vẫn ẩn.
    await page.evaluate(() => window.scrollTo(0, 400));
    await page.waitForTimeout(350);
    expect(await headerIsHidden(page)).toBe(true);

    // Kéo ngược lên: hiện.
    await page.evaluate(() => window.scrollBy(0, -120));
    await expect.poll(() => headerIsShown(page)).toBe(true);

    // Kéo xuống lần nữa: lại ẩn.
    await page.evaluate(() => window.scrollBy(0, 220));
    await expect.poll(() => headerIsHidden(page)).toBe(true);
  });

  test('TC-FEAT-HDR-05 sticky offset follows the header so no gap is left behind', async ({ page }) => {
    await openManage(page, { tab: 'overview' });
    const offset = () => page.evaluate(() => getComputedStyle(document.documentElement).getPropertyValue('--app-header-height').trim());
    await expect.poll(() => headerIsHidden(page), { timeout: HEADER_AUTO_HIDE_ENTRY_DELAY_MS + 3000 }).toBe(true);
    await expect.poll(offset).toBe('0px');
    await page.evaluate(() => window.scrollTo(0, 400));
    // Header chấm điểm cuộn theo khung hình: hai lần cuộn sát nhau bị gộp thành một.
    await page.waitForTimeout(250);
    await page.evaluate(() => window.scrollBy(0, -120));
    await expect.poll(() => headerIsShown(page)).toBe(true);
    await expect.poll(offset).not.toBe('0px');
  });

  test('TC-FEAT-HDR-07 keyboard focus inside the hidden header reveals it', async ({ page }) => {
    await openManage(page, { tab: 'overview' });
    await expect.poll(() => headerIsHidden(page), { timeout: HEADER_AUTO_HIDE_ENTRY_DELAY_MS + 3000 }).toBe(true);
    await page.locator('header a, header button').first().focus();
    await expect.poll(() => headerIsShown(page)).toBe(true);
  });
});

test.describe('header auto-hide: no change where it does not apply', () => {
  test('TC-FEAT-HDR-08 desktop width keeps the header and never scrolls the page by itself', async ({ page }) => {
    await page.setViewportSize({ width: 1280, height: 800 });
    await openManage(page, { tab: 'overview' });
    await expect(page.locator('header')).toBeVisible();
    await page.waitForTimeout(HEADER_AUTO_HIDE_ENTRY_DELAY_MS + 800);
    // Trên máy tính hook không được tự cuộn một đoạn bằng chiều cao header như trên điện thoại.
    expect(await page.evaluate(() => window.scrollY)).toBe(0);
    await page.evaluate(() => window.scrollTo(0, 500));
    await page.waitForTimeout(400);
    expect(await headerIsShown(page)).toBe(true);
  });
});

// Trang live cũng tự ẩn header trên điện thoại: nó không còn nằm ngoài luật.
const liveMatchId = 'header-live-match';
async function fulfillJson(route: Route, data: unknown) {
  const requestHeaders = route.request().headers();
  const headers = {
    'access-control-allow-origin': requestHeaders.origin ?? 'http://localhost:3001',
    'access-control-allow-credentials': 'true',
    'access-control-allow-methods': 'GET, POST, OPTIONS',
    'access-control-allow-headers': requestHeaders['access-control-request-headers'] ?? 'authorization,content-type',
  };
  if (route.request().method() === 'OPTIONS') return route.fulfill({ status: 204, headers });
  return route.fulfill({ status: 200, headers, json: { data } });
}

test.describe('header auto-hide: live page follows the same rule', () => {
  test.use({ viewport: { width: 390, height: 664 }, isMobile: true, hasTouch: true });

  test('TC-FEAT-HDR-09 live page header slides away on entry and returns when scrolling up', async ({ page }) => {
    await page.route('**/api/v1/**', async (route) => {
      const { pathname } = new URL(route.request().url());
      if (pathname === `/api/v1/matches/${liveMatchId}`) {
        return fulfillJson(route, {
          id: liveMatchId, groupId: 'g', tournamentId: 't', status: 'ONGOING', roundNumber: 1, matchOrder: 1, bracketBranch: 'WINNER',
          isBye: false, revision: 1, p1SetsWon: 0, p2SetsWon: 0, participant1Id: 'p1', participant2Id: 'p2',
          participant1: { id: 'p1', teamName: 'A', members: [] }, participant2: { id: 'p2', teamName: 'B', members: [] },
          scoreDetails: { sets: [] }, tournament: { id: 't', name: 'T', categoryName: 'Cầu lông', categorySlug: 'badminton', createdBy: 'x' },
        });
      }
      return fulfillJson(route, []);
    });
    await page.goto(`/live/${liveMatchId}`, { waitUntil: 'domcontentloaded' });
    await expect(page.locator('header')).toBeVisible();
    // Dưới khung stage còn thanh thông tin giải nên trang có chỗ cuộn bằng chiều cao header.
    await page.waitForTimeout(HEADER_AUTO_HIDE_ENTRY_DELAY_MS + 800);
    expect(await headerIsShown(page)).toBe(false);
    await page.evaluate(() => window.scrollTo(0, 0));
    await page.waitForTimeout(400);
    expect(await headerIsShown(page)).toBe(true);
  });
});

