  3. Change da archive TRONG NHANH NAY (so voi origin/<target>) ma tasks.md con o "- [ ]".
Exit 0 = qua, 1 = chan, 2 = khong chay duoc (thieu openspec CLI, khong co openspec/).
"""
import json
import os
import re
import shutil
import subprocess
import sys


REQ = re.compile(r"^###\s+Requirement:\s*(.+?)\s*$")
SCEN = re.compile(r"^####\s+Scenario:\s*(.+?)\s*$")


def parse_spec(text):
    """{ten requirement: {ten scenario}} cua mot file spec (chung hoac mot khoi delta)."""
    out, cur = {}, None
    for line in text.splitlines():
        if line.startswith("## "):
            cur = None
        m = REQ.match(line)
        if m:
            cur = m.group(1)
            out.setdefault(cur, set())
            continue
        m = SCEN.match(line)
        if m and cur is not None:
            out[cur].add(m.group(1))
    return out


def parse_delta(text):
    """Tach delta thanh KEEP (ADDED+MODIFIED: req -> scenarios), REMOVED, RENAMED_FROM."""
    sections, name = {}, None
    for line in text.splitlines():
        m = re.match(r"^##\s+(ADDED|MODIFIED|REMOVED|RENAMED)\s+Requirements", line)
        if m:
            name = m.group(1)
            sections.setdefault(name, [])
            continue
        if name:
            sections[name].append(line)
    keep = {}
    for key in ("ADDED", "MODIFIED"):
        for req, sc in parse_spec("\n".join(sections.get(key, []))).items():
            keep.setdefault(req, set()).update(sc)
    removed = set(parse_spec("\n".join(sections.get("REMOVED", []))))
    renamed = set(re.findall(r"FROM:\s*`?###\s*Requirement:\s*([^`\n]+?)`?\s*$", "\n".join(sections.get("RENAMED", [])), re.MULTILINE))
    return {"KEEP": keep, "REMOVED": removed, "RENAMED_FROM": renamed}


UNCHECKED = re.compile(r"^\s*[-*]\s+\[(?![xX]\s*\])[^\]]*\]", re.MULTILINE)


def run(*args):
    # Khong dung shell: tham so (vd target tu argv) khong bao gio duoc shell dien giai.
    # Tren Windows `openspec` la openspec.cmd; shutil.which tra duong dan day du de CreateProcess chay duoc.
    exe = shutil.which(args[0]) or args[0]
    return subprocess.run([exe, *args[1:]], capture_output=True, text=True, encoding="utf-8")


def main():
    target = sys.argv[1] if len(sys.argv) > 1 else "main"
    if not re.fullmatch(r"[A-Za-z0-9._/-]+", target):
        print(f"[openspec-gate] Ten nhanh dich khong hop le: {target!r}", file=sys.stderr)
        return 2
    if not os.path.isdir("openspec"):
