        return 0
    problems = []

    v = run("openspec", "validate", "--all", "--strict")
    if v.returncode != 0:
        problems.append("validate --all --strict loi:\n" + (v.stdout + v.stderr).strip())

    ls = run("openspec", "list", "--json")
